// ===== 02_sunucu.js =====
// ---------- Sunucu bağlantısı ----------
// Supabase'in istemcinin kullandığı üç parçası: giriş (Auth), api çağrısı (PostgREST, yalnız `api` şeması) ve canlı yayın
// (Realtime, yalnız özel kanallar; D-074). Paket yok: fetch ve WebSocket. Yerel sunucu taklidi (tools/yerel_sunucu) aynı
// iletişim kurallarını konuşur. Ayar `yapilandirma.json` dosyasından gelir (Supabase adresi ve herkese açık anahtar).

class SunucuHatasi extends Error {
  constructor(kod, ileti, ayrinti = "", durum = 0) {
    super(ileti);
    this.kod = kod;
    this.ayrinti = ayrinti;
    this.durum = durum;
  }
}

// Giriş hatalarının iletisi (Supabase Auth hata kodları).
const GIRIS_HATALARI = {
  invalid_credentials: ç("E-posta ya da parola yanlış."),
  email_not_confirmed: ç("Önce e-postana gelen bağlantıya tıklayarak adresini doğrula."),
  weak_password: ç("Parola en az 8 karakter olmalı."),
  validation_failed: ç("E-posta adresi geçersiz görünüyor."),
  email_address_invalid: ç("E-posta adresi geçersiz görünüyor."),
  over_email_send_rate_limit: ç("Çok sık e-posta istendi; birkaç dakika sonra yeniden dene."),
  over_request_rate_limit: ç("Çok sık denendi; biraz bekleyip yeniden dene."),
  user_already_exists: ç("Bu e-posta ile zaten bir hesap var; giriş yapmayı dene."),
  email_exists: ç("Bu e-posta ile zaten bir hesap var; giriş yapmayı dene."),
  same_password: ç("Yeni parola eskisiyle aynı olamaz."),
  refresh_token_not_found: ç("Oturumun sona erdi; yeniden giriş yap."),
  refresh_token_already_used: ç("Oturumun sona erdi; yeniden giriş yap."),
  session_not_found: ç("Oturumun sona erdi; yeniden giriş yap."),
  otp_expired: ç("Bağlantının süresi dolmuş ya da daha önce kullanılmış. Yeni bir bağlantı iste."),
  signup_disabled: ç("Şu an yeni kayıt alınmıyor."),
};

// Sunucunun hata iletisi (game.fail'in Türkçe ipucu): İngilizcede katalogdan. Sayı taşıyan iletiler sunucudaki format
// kalıbıyla eşlenir ("Paylaşım en fazla %s harf olabilir." → "A post can be at most %s characters."); eşleşme yoksa hata
// koduna göre ("HATA:KOD"), o da yoksa genel ileti. Sunucu iletilerinin listesi (apps/istemci/dil/sunucu.json) ve
// İngilizcesinin tamlığı tools/istemci/dil.test.ts'te denetlenir.
let sunucuKaliplari = null;
function sunucuIletisi(kod, ileti) {
  if (DIL.kod === "tr") return ileti || ç("İşlem yapılamadı.");
  const k = DIL.katalog;
  if (ileti && typeof k[ileti] === "string") return k[ileti];
  if (ileti) {
    sunucuKaliplari ??= Object.keys(k).filter((x) => x.includes("%s") && typeof k[x] === "string").map((x) => [
      new RegExp("^" + x.split("%s").map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("(.+?)") + "$"), k[x]]);
    for (const [re, en] of sunucuKaliplari) {
      const m = ileti.match(re);
      if (m) { let i = 1; return en.replace(/%s/g, () => m[i++] ?? ""); }
    }
  }
  return (typeof k["HATA:" + kod] === "string" && k["HATA:" + kod]) || ç("İşlem yapılamadı.");
}

const Sunucu = (() => {
  const DEPO = "civora.oturum";
  let ayar = null;
  let oturum = null;
  let yenileniyor = null;
  const oturumDinleyici = new Set();

  const depoOku = () => { try { return JSON.parse(localStorage.getItem(DEPO) ?? "null"); } catch { return null; } };
  const depoYaz = (o) => { try { o ? localStorage.setItem(DEPO, JSON.stringify(o)) : localStorage.removeItem(DEPO); } catch { /* özel pencere */ } };

  function oturumKoy(o) {
    oturum = o ? { access_token: o.access_token, refresh_token: o.refresh_token, expires_at: Number(o.expires_at) || 0,
      user: o.user ?? oturum?.user ?? null } : null;
    depoYaz(oturum);
    for (const f of oturumDinleyici) { try { f(oturum); } catch (e) { console.error(e); } }
  }

  function siteAdresi() {
    return location.origin + location.pathname;
  }

  async function yukle() {
    const r = await fetch("yapilandirma.json", { cache: "no-store" });
    if (!r.ok) throw new SunucuHatasi("CONFIG_MISSING", ç("Oyunun ayar dosyası bulunamadı."));
    ayar = await r.json();
    oturum = depoOku();
  }

  // Ham istek: ağ hatası "AĞ" kodlu SunucuHatasi olur.
  // Supabase'in yeni herkese açık anahtarı (sb_publishable_…) JWT değildir: yalnız "apikey" başlığında gider; "Authorization"
  // başlığında yalnız oturum jetonu (ya da eski tür anon JWT anahtarı) taşınır.
  async function ham(yol, { yontem = "POST", govde, token, basliklar = {} } = {}) {
    let r;
    const yetki = token ?? (String(ayar.anahtar).startsWith("eyJ") ? ayar.anahtar : null);
    try {
      r = await fetch(ayar.supabaseUrl + yol, {
        method: yontem,
        headers: { apikey: ayar.anahtar, "content-type": "application/json", ...(yetki ? { authorization: "Bearer " + yetki } : {}),
          "x-supabase-api-version": "2024-01-01", ...basliklar },
        body: govde === undefined ? undefined : JSON.stringify(govde),
      });
    } catch {
      throw new SunucuHatasi("AG", ç("Sunucuya ulaşılamadı. İnternet bağlantını denetle."), "", 0);
    }
    const metin = await r.text();
    let veri = null;
    try { veri = metin ? JSON.parse(metin) : null; } catch { veri = metin; }
    return { durum: r.status, ok: r.ok, veri };
  }

  function girisHatasi(r) {
    const v = r.veri ?? {};
    const kod = v.error_code ?? (typeof v.code === "string" ? v.code : null) ?? v.error ?? "AUTH_" + r.durum;
    return new SunucuHatasi(kod, GIRIS_HATALARI[kod] ?? v.msg ?? v.message ?? v.error_description ?? ç("Giriş işlemi yapılamadı."), "", r.durum);
  }

  // ---------------- Giriş ----------------
  const Giris = {
    get oturum() { return oturum; },
    get kullanici() { return oturum?.user ?? null; },
    dinle(f) { oturumDinleyici.add(f); return () => oturumDinleyici.delete(f); },

    async kayit(email, parola) {
      // Dil kimlik hesabına da yazılır: doğrulama ve parola e-postası bu dilde gider (docs/YAYIN.md, e-posta şablonları; D-096)
      const r = await ham("/auth/v1/signup?redirect_to=" + encodeURIComponent(siteAdresi()), { govde: { email, password: parola, data: { locale: DIL.kod } } });
      if (!r.ok) throw girisHatasi(r);
      // E-posta doğrulaması açıkken oturum gelmez; bağlantı e-postayla gider (D-015).
      if (r.veri?.access_token) oturumKoy(r.veri);
      return { dogrulamaGerekli: !r.veri?.access_token };
    },

    async giris(email, parola) {
      const r = await ham("/auth/v1/token?grant_type=password", { govde: { email, password: parola } });
      if (!r.ok) throw girisHatasi(r);
      oturumKoy(r.veri);
      return oturum;
    },

    async yenile() {
      if (!oturum?.refresh_token) throw new SunucuHatasi("NOT_AUTHENTICATED", ç("Giriş yapılmamış."));
      if (!yenileniyor) {
        yenileniyor = (async () => {
          const r = await ham("/auth/v1/token?grant_type=refresh_token", { govde: { refresh_token: oturum.refresh_token } });
          if (!r.ok) {
            if (r.durum >= 400 && r.durum < 500) oturumKoy(null);
            throw girisHatasi(r);
          }
          oturumKoy(r.veri);
        })().finally(() => { yenileniyor = null; });
      }
      return yenileniyor;
    },

    async gecerliJeton() {
      if (!oturum) return null;
      if (oturum.expires_at * 1000 - Date.now() < 60_000) await Giris.yenile();
      return oturum.access_token;
    },

    async cikis() {
      const t = oturum?.access_token;
      oturumKoy(null);
      if (t) await ham("/auth/v1/logout", { token: t }).catch(() => {});
    },

    async sifirlamaIste(email) {
      const r = await ham("/auth/v1/recover?redirect_to=" + encodeURIComponent(siteAdresi()), { govde: { email } });
      if (!r.ok) throw girisHatasi(r);
    },

    async parolaDegistir(yeni) {
      const t = await Giris.gecerliJeton();
      const r = await ham("/auth/v1/user", { yontem: "PUT", token: t, govde: { password: yeni } });
      if (!r.ok) throw girisHatasi(r);
    },

    // Kimlik hesabındaki dil (e-postaların dili); hata yutulur, oyun dili hesaptaki profiles.locale'dedir
    async dilYaz(kod) {
      const t = await Giris.gecerliJeton().catch(() => null);
      if (t) await ham("/auth/v1/user", { yontem: "PUT", token: t, govde: { data: { locale: kod } } }).catch(() => {});
    },

    async dogrulamaYenidenGonder(email) {
      const r = await ham("/auth/v1/resend", { govde: { type: "signup", email, options: { emailRedirectTo: siteAdresi() } } });
      if (!r.ok) throw girisHatasi(r);
    },

    // E-postadaki bağlantıdan dönüş: adres çubuğundaki #access_token=… ya da #error=… işlenir, sonra temizlenir.
    adresiIsle() {
      const h = location.hash.startsWith("#") ? location.hash.slice(1) : "";
      if (!h.includes("access_token=") && !h.includes("error=")) return null;
      const p = new URLSearchParams(h);
      history.replaceState(null, "", location.pathname + location.search);
      if (p.get("error")) {
        const kod = p.get("error_code") ?? p.get("error");
        return { hata: new SunucuHatasi(kod, GIRIS_HATALARI[kod] ?? p.get("error_description") ?? ç("Bağlantı geçersiz.")) };
      }
      oturumKoy({ access_token: p.get("access_token"), refresh_token: p.get("refresh_token"),
        expires_at: Number(p.get("expires_at")) || Math.floor(Date.now() / 1000) + Number(p.get("expires_in") || 3600), user: null });
      return { tur: p.get("type") ?? "signup" };
    },

    async kullaniciGetir() {
      const t = await Giris.gecerliJeton();
      const r = await ham("/auth/v1/user", { yontem: "GET", token: t });
      if (!r.ok) throw girisHatasi(r);
      oturum.user = r.veri;
      depoYaz(oturum);
      return r.veri;
    },
  };

  // ---------------- api çağrısı ----------------
  // İşlem anahtarı: aynı istek ağ hatasında aynı anahtarla yeniden gönderilir; sunucu ikinciyi tekrar yapmaz.
  const anahtar = () => (crypto.randomUUID ? crypto.randomUUID() : Date.now().toString(36) + Math.random().toString(36).slice(2, 12));

  async function cagir(fn, args = {}, { deneme = 0 } = {}) {
    const token = await Giris.gecerliJeton().catch(() => null);
    const r = await ham("/rest/v1/rpc/" + fn, { govde: args, token: token ?? undefined,
      basliklar: { "content-profile": "api", "accept-profile": "api" } }).catch((e) => {
      if (e.kod === "AG" && "p_idempotency_key" in args && deneme < 2) return null;
      throw e;
    });
    if (r === null) {
      await new Promise((ok) => setTimeout(ok, 800 * (deneme + 1)));
      return cagir(fn, args, { deneme: deneme + 1 });
    }
    if (r.ok) return r.veri;
    const v = r.veri ?? {};
    if (r.durum === 401 && token && deneme === 0) {
      await Giris.yenile().catch(() => {});
      if (oturum) return cagir(fn, args, { deneme: 1 });
    }
    if (v.code === "P0001") throw new SunucuHatasi(v.message, sunucuIletisi(v.message, v.hint), v.details ?? "", r.durum);
    if (r.durum === 401 || v.code === "42501") throw new SunucuHatasi("NOT_AUTHENTICATED", ç("Bu işlem için giriş yapmalısın."), "", r.durum);
    if (v.code === "PGRST202") throw new SunucuHatasi("API_MISSING", ç("Uygulama sunucudan yeni; sayfayı yenile."), v.message ?? "", r.durum);
    throw new SunucuHatasi(v.code ?? "HATA_" + r.durum, ç("Beklenmeyen bir sorun oldu; biraz sonra yeniden dene."), v.message ?? "", r.durum);
  }

  // Yazma çağrısı: işlem anahtarını kendisi üretir.
  const yap = (fn, args = {}) => cagir(fn, { p_idempotency_key: anahtar(), ...args });

  // ---------------- canlı yayın ----------------
  const Canli = (() => {
    let ws = null;
    let ref = 0;
    let kalp = null;
    let bekleme = 1000;
    let kapatildi = true;
    const kanallar = new Map();     // konu → { isleyiciler:Set, katildi:boolean, joinRef }
    const durumDinleyici = new Set();
    let bagliMi = false;

    const gonder = (m) => { if (ws?.readyState === 1) ws.send(JSON.stringify(m)); };
    const durumBildir = (b) => { bagliMi = b; for (const f of durumDinleyici) f(b); };

    function katil(konu) {
      const k = kanallar.get(konu);
      if (!k || !oturum) return;
      k.joinRef = String(++ref);
      gonder({ topic: "realtime:" + konu, event: "phx_join", ref: k.joinRef, join_ref: k.joinRef,
        payload: { config: { broadcast: { ack: false, self: false }, presence: { key: "", enabled: false }, postgres_changes: [], private: true },
          access_token: oturum.access_token } });
    }

    function ac() {
      if (!ayar || !oturum || ws) return;
      kapatildi = false;
      const adres = ayar.supabaseUrl.replace(/^http/, "ws") + "/realtime/v1/websocket?apikey=" + encodeURIComponent(ayar.anahtar) + "&vsn=1.0.0";
      ws = new WebSocket(adres);
      ws.onopen = () => {
        bekleme = 1000;
        durumBildir(true);
        for (const konu of kanallar.keys()) katil(konu);
        kalp = setInterval(() => gonder({ topic: "phoenix", event: "heartbeat", payload: {}, ref: String(++ref) }), 25_000);
      };
      ws.onmessage = (m) => {
        let i;
        try { i = JSON.parse(m.data); } catch { return; }
        const konu = typeof i.topic === "string" && i.topic.startsWith("realtime:") ? i.topic.slice(9) : null;
        const k = konu ? kanallar.get(konu) : null;
        if (!k) return;
        if (i.event === "phx_reply" && i.ref === k.joinRef) {
          k.katildi = i.payload?.status === "ok";
          if (!k.katildi) console.warn("canlı yayın kanalı reddedildi:", konu, i.payload?.response);
          return;
        }
        if (i.event === "phx_close" || i.event === "phx_error") { k.katildi = false; setTimeout(() => katil(konu), 3000); return; }
        if (i.event === "broadcast") {
          const p = i.payload ?? {};
          for (const f of k.isleyiciler) { try { f(p.event, p.payload ?? {}); } catch (e) { console.error(e); } }
        }
      };
      ws.onclose = () => {
        clearInterval(kalp);
        ws = null;
        durumBildir(false);
        for (const k of kanallar.values()) k.katildi = false;
        if (!kapatildi && oturum) { setTimeout(ac, bekleme); bekleme = Math.min(bekleme * 2, 30_000); }
      };
      ws.onerror = () => {};
    }

    function kapat() {
      kapatildi = true;
      clearInterval(kalp);
      if (ws) { ws.onclose = null; ws.close(); ws = null; }
      durumBildir(false);
    }

    // Bir konuyu dinler; dönen işlev dinlemeyi bırakır.
    function dinle(konu, f) {
      let k = kanallar.get(konu);
      if (!k) { k = { isleyiciler: new Set(), katildi: false, joinRef: null }; kanallar.set(konu, k); katil(konu); }
      k.isleyiciler.add(f);
      ac();
      return () => {
        k.isleyiciler.delete(f);
        if (k.isleyiciler.size === 0) {
          kanallar.delete(konu);
          gonder({ topic: "realtime:" + konu, event: "phx_leave", payload: {}, ref: String(++ref) });
        }
      };
    }

    // Oturum yenilenince açık kanallara yeni jeton; çıkışta bağlantı kapanır.
    Giris.dinle((o) => {
      if (!o) { kanallar.clear(); kapat(); return; }
      for (const konu of kanallar.keys()) gonder({ topic: "realtime:" + konu, event: "access_token", payload: { access_token: o.access_token }, ref: String(++ref) });
    });
    addEventListener("online", () => { if (!ws && oturum && kanallar.size) ac(); });

    return { dinle, kapat, get bagli() { return bagliMi; }, durum(f) { durumDinleyici.add(f); return () => durumDinleyici.delete(f); } };
  })();

  return { yukle, Giris, cagir, yap, anahtar, Canli, get ayar() { return ayar; } };
})();

// ===== 03_durum.js =====
// ---------- Durum: sunucudan okunan veriler, olaylar ve canlı yayın ----------
// Ekranlar veriyi buradan alır ve "dinle" ile değişikliği izler. Kişisel kanal (user:<kimlik>) ve ülke kanalı
// (country:<ülke>) giriş yapılınca dinlenir; gelen olay ilgili veriyi tazeler ve kısa bir bildirim gösterir.

// Kişisel olayların bildirimi (olay sırası türleri; docs/VERITABANI.md). Metinde kişi adı yok, veri sunucudan okunur.
const BILDIRIM = {
  "job.completed": () => [ç("İşin tamamlandı; ücretin hesabına geçti."), "briefcase-business"],
  "job.contract_started": () => [ç("İşletmende yeni bir iş başladı."), "factory"],
  "job.company_completed": (d) => [d.output_qty ? ç("İşletmende bir iş bitti: {n} {urun} depoya girdi.", { n: Number(d.output_qty), urun: varlikAdi(d.output_asset) })
    : ç("İşletmende bir iş bitti."), "factory"],
  "training.completed": () => [ç("Eğitimin bitti; becerin yükseldi."), "graduation-cap"],
  "travel.arrived": () => [ç("Yolculuğun bitti; vardın."), "map-pin"],
  "market.sale_receipt": () => [ç("Pazarda bir satış yaptın."), "store"],
  "market.purchase_receipt": () => [ç("Alışverişin tamamlandı."), "store"],
  "war.rank_up": (d) => [d.rank_name ? ç("Rütben yükseldi: {r}", { r: çv(d.rank_name) }) : ç("Rütben yükseldi!"), "medal"],
  "progress.level_up": (d) => [d.level ? ç("Seviye atladın: {n}. seviye; enerji barın doldu.", { n: Number(d.level) }) : ç("Seviye atladın!"), "sparkles"],
  "dm.request": () => [ç("Yeni bir özel mesaj isteğin var."), "message-circle"],
  "dm.message": () => [ç("Yeni özel mesaj."), "message-circle"],
  "friend.request": () => [ç("Yeni arkadaşlık isteği."), "user-round-plus"],
  "friend.accepted": () => [ç("Arkadaşlık isteğin kabul edildi."), "users-round"],
  "feedback.answered": () => [ç("Geri bildirimine yanıt geldi (Ayarlar → Geri bildirim)."), "badge-check"],
  "house.sold": () => [ç("Evin satıldı."), "house"],
  "square.replied": () => [ç("Meydan'daki paylaşımına yanıt geldi."), "message-circle"],
  "citizenship.changed": () => [ç("Vatandaşlığın değişti."), "id-card"],
  "account.deletion_requested": () => [ç("Hesap silme talebin alındı; bekleme süresinde vazgeçebilirsin."), "circle-alert"],
  // Kaçakçılık (D-097): sonuç varışta sunucunun zarıyla belli olur. Kefaletle çıkış kendi işlemin olduğundan bildirilmez.
  "shadow.run_resolved": (d) => d.status === "sold" ? [ç("Kaçak yük satıldı: {kr} kredi kazandın.", { kr: kr(d.payout_cr) }), "coins"]
    : d.status === "caught" ? [ç("Gümrükte yakalandın: yük ve {kr} kredi ceza el kondu, gözaltındasın.", { kr: kr(d.fine_cr) }), "lock"] : null,
  // Kara borsa (D-105): satıcıya; alıcının kendi alımı ekranda görünür
  "black_market.sold": (d) => [ç("Kara borsadaki ilanından {n} {urun} satıldı: {kr} kredi, vergisiz.", { n: sayi(d.qty), urun: varlikAdi(d.asset), kr: kr(d.total_cr) }), "coins"],
  "black_market.raided": (d) => [ç("Kara borsada baskın: ilanından {n} {urun} el kondu, {kr} kredi ceza ödedin; ilan kapandı.", { n: sayi(d.qty), urun: varlikAdi(d.asset), kr: kr(d.fine_cr) }), "shield"],
  "black_market.expired": () => [ç("Kara borsadaki ilanının süresi doldu; kalan malın ve ceza payın sana döndü."), "timer"],
};

// Ülke kanalının bildirimleri (country:<ülke>; vatandaşlara). Seçim, meclis ve savaş duyuruları.
const ULKE_BILDIRIM = {
  "election.candidacy_opened": () => [ç("Seçimde adaylık dönemi başladı (Ülkem → Seçim)."), "megaphone"],
  "election.voting_opened": () => [ç("Seçimde oylama başladı. Oyunu ver!"), "vote"],
  "election.runoff": () => [ç("Seçimde eşitlik çıktı; ikinci tur başladı."), "vote"],
  "election.certified": () => [ç("Seçim sonuçları açıklandı."), "trophy"],
  "office.installed": () => [ç("Yeni başkan ve meclis göreve başladı."), "landmark"],
  "parliament.motion_opened": () => [ç("Mecliste yeni bir oylama açıldı."), "gavel"],
  // D-103: uyuyan ülke uyanınca ve yeniden uyuyunca
  "country.awoke": (d) => [d.founding_election_id ? ç("Ülken uyandı: {n} etkin vatandaş. Kurucu Meclis seçimi başladı (Ülkem → Seçim).", { n: Number(d.active_citizens) })
    : ç("Ülken yeniden uyandı: {n} etkin vatandaş; savaş yeniden açık.", { n: Number(d.active_citizens) }), "sun"],
  "country.dormant": (d) => [ç("Ülken uyudu: etkin vatandaş {n}, gereken {esik}. Uyurken savaş açılamaz.", { n: Number(d.active_citizens), esik: Number(d.min_active) }), "moon"],
  "customs.seizure": (d) => [ç("Gümrüğümüz bir kaçakçı yakaladı: {n} {urun} el kondu, {kr} kredi ceza hazineye geçti.",
    { n: sayi(d.qty), urun: varlikAdi(d.asset), kr: kr(d.fine_cr) }), "shield"],
  "black_market.raid": (d) => [ç("Kara borsada baskın ({bolge}): {n} {urun} el kondu, {kr} kredi ceza hazineye geçti.",
    { bolge: bolgeAdi(d.region_id), n: sayi(d.qty), urun: varlikAdi(d.asset), kr: kr(d.fines_cr) }), "shield"],
  "parliament.motion_closed": (d) => [d.status === "passed" ? ç("Meclis bir öneriyi kabul etti.") : ç("Mecliste bir öneri kabul edilmedi."), "gavel"],
  "country.war_declared": (d, ulke) => [d.defender_country_id === ulke
    ? ç("Ülkene savaş ilan edildi! Hedef: {yer}.", { yer: bolgeAdi(d.target_region_id) }) : ç("Savaş ilan ettik. Hedef: {yer}.", { yer: bolgeAdi(d.target_region_id) }), "swords"],
  "country.war_started": (d) => [ç("Savaş başladı: {yer}. Cepheye!", { yer: bolgeAdi(d.target_region_id) }), "swords"],
  "country.war_closed": (d, ulke) => {
    const biz = d.attacker_country_id === ulke;
    const yer = bolgeAdi(d.target_region_id);
    if (d.status === "attacker_won") return [biz ? ç("Zafer! {yer} artık bizim.", { yer }) : ç("{yer} düştü.", { yer }), "swords"];
    if (d.status === "defender_won") return [biz ? ç("Taarruz başarısız: {yer} alınamadı.", { yer }) : ç("Savunma kazandı: {yer} bizde kaldı.", { yer }), "shield"];
    if (d.status === "cancelled") return [ç("Kampanya iptal edildi: {yer}.", { yer }), "swords"];
    if (d.status === "peace") return [ç("Barışla kapandı: {yer}.", { yer }), "handshake"];
    return [ç("Kampanya kapandı: {yer}.", { yer }), "swords"];
  },
};

// Diplomasi duyuruları (public:treaty, herkese açık): yalnız kendi ülkenin taraf olduğu antlaşmalar bildirilir. Teklifi
// yapan ya da geri çeken başkana kendi işleminin haberi gitmez (ekranı söyler); kabul ve fesih iki ülkeye de duyurulur.
const antlasmaAdi = (d, ulke) => {
  const ulkeAd = ulkeAdi(d.country_a === ulke ? d.country_b : d.country_a);
  return d.kind === "peace" ? ç("Barış antlaşması ({ulke})", { ulke: ulkeAd }) : ç("Saldırmazlık antlaşması ({ulke})", { ulke: ulkeAd });
};
const DIPLOMASI_BILDIRIM = {
  "diplomacy.offered": (d, u) => (d.country_b === u ? [d.kind === "peace"
    ? ç("{ulke} barış teklif etti (Ülkem → Diplomasi).", { ulke: ulkeAdi(d.country_a) })
    : ç("{ulke} saldırmazlık teklif etti (Ülkem → Diplomasi).", { ulke: ulkeAdi(d.country_a) }), "handshake"] : null),
  "diplomacy.accepted": (d, u) => [ç("{antlasma} kabul edildi; iki meclisin onayına gitti.", { antlasma: antlasmaAdi(d, u) }), "handshake"],
  "diplomacy.rejected": (d, u) => (d.country_a === u ? [ç("{antlasma}: teklif reddedildi.", { antlasma: antlasmaAdi(d, u) }), "handshake"] : null),
  "diplomacy.withdrawn": (d, u) => (d.country_b === u ? [ç("{antlasma}: teklif geri çekildi.", { antlasma: antlasmaAdi(d, u) }), "handshake"] : null),
  "diplomacy.in_force": (d, u) => [ç("{antlasma} yürürlüğe girdi.", { antlasma: antlasmaAdi(d, u) }), "handshake"],
  "diplomacy.termination_notice": (d, u) => [ç("{antlasma} için fesih bildirildi.", { antlasma: antlasmaAdi(d, u) }), "handshake"],
  "diplomacy.failed": (d, u) => [ç("{antlasma} onaylanmadı.", { antlasma: antlasmaAdi(d, u) }), "handshake"],
};

const Durum = (() => {
  const v = { ozet: null, askerlik: null, kurallar: null, secenekler: null, harita: null };
  const dinleyici = new Map();
  let kanallar = [];

  function dinle(ad, f) {
    if (!dinleyici.has(ad)) dinleyici.set(ad, new Set());
    dinleyici.get(ad).add(f);
    return () => dinleyici.get(ad)?.delete(f);
  }
  function yay(ad, veri) {
    for (const f of dinleyici.get(ad) ?? []) { try { f(veri); } catch (e) { console.error(e); } }
  }

  // Oturumdaki kullanıcı kimliği (jetonun "sub" alanı).
  function kimlik() {
    const t = Sunucu.Giris.oturum?.access_token;
    if (!t) return null;
    try { return JSON.parse(atob(t.split(".")[1].replace(/-/g, "+").replace(/_/g, "/"))).sub ?? null; } catch { return null; }
  }

  async function kurallar() {
    if (!v.kurallar) v.kurallar = await Sunucu.cagir("rules");
    return v.kurallar;
  }
  async function ozet() {
    v.ozet = await Sunucu.cagir("me_overview");
    yay("ozet", v.ozet);
    return v.ozet;
  }
  async function askerlik() {
    v.askerlik = await Sunucu.cagir("military_overview");
    yay("askerlik", v.askerlik);
    return v.askerlik;
  }

  // Dünya haritası: bölgelerin bugünkü sahibi ve açık ülkeler (api.world_map). Kısa önbellek: seyahat ve harita ekranı
  // aynı veriyi kullanır; fetih olunca ekran taze okur.
  let haritaAn = 0;
  async function harita(taze = false) {
    if (!taze && v.harita && Date.now() - haritaAn < 30000) return v.harita;
    const h = await Sunucu.cagir("world_map");
    v.harita = { ...h, sahip: Object.fromEntries(h.regions.map(([id, sahip]) => [id, sahip])) };
    haritaAn = Date.now();
    return v.harita;
  }

  // Kişinin stoğu: "ürün@kalite" → harcanabilir miktar.
  const stok = (varlik) => v.ozet?.balances?.find((b) => b.asset === varlik)?.spendable ?? 0;

  function kisisel(olay, yuk) {
    yay("olay", { olay, yuk });
    // Kendi yazdığın mesajın kopyası (öteki cihazların için gelir) bildirim olarak gösterilmez.
    const kendim = yuk?.data?.author_id && yuk.data.author_id === v.ozet?.character?.id;
    const b = kendim ? null : BILDIRIM[olay]?.(yuk?.data ?? {});
    if (b) tost(b[0], b[1]);
    if (/^(market\.|job\.|training\.|travel\.|house\.|citizenship\.|war\.|shadow\.|detention\.)/.test(olay)) ozet().catch(() => {});
    if (/^(training\.|war\.|progress\.)/.test(olay)) askerlik().catch(() => {});
  }

  function canliBaslat() {
    canliBitir();
    const uid = kimlik();
    if (!uid) return;
    kanallar.push(Sunucu.Canli.dinle("user:" + uid, kisisel));
    const ulke = v.ozet?.character?.citizenship;
    if (ulke) kanallar.push(Sunucu.Canli.dinle("country:" + ulke, (olay, yuk) => {
      yay("ulke-olay", { olay, yuk });
      const b = ULKE_BILDIRIM[olay]?.(yuk?.data ?? {}, ulke);
      if (b) tost(b[0], b[1]);
      if (/^(country\.war_|office\.installed)/.test(olay)) askerlik().catch(() => {});
    }));
    // Antlaşmalar herkese açık kanaldan; yalnız kendi ülkenin taraf olduğu olaylar.
    if (ulke) kanallar.push(Sunucu.Canli.dinle("public:treaty", (olay, yuk) => {
      const d = yuk?.data ?? {};
      if (d.country_a !== ulke && d.country_b !== ulke) return;
      yay("diplomasi", { olay, yuk });
      const b = DIPLOMASI_BILDIRIM[olay]?.(d, ulke);
      if (b) tost(b[0], b[1]);
    }));
  }
  function canliBitir() {
    for (const f of kanallar) f();
    kanallar = [];
  }

  function temizle() {
    canliBitir();
    v.ozet = v.askerlik = v.kurallar = v.secenekler = v.harita = null;
  }

  return { v, dinle, yay, kimlik, kurallar, ozet, askerlik, harita, stok, canliBaslat, canliBitir, temizle };
})();

// Sunucu hatasını kullanıcıya gösterilecek metne çevirir.
const hataMetni = (e) => (e instanceof SunucuHatasi ? e.message : ç("Beklenmeyen bir sorun oldu; sayfayı yenileyip yeniden dene."));

// Geri sayım: kök içindeki [data-bitis] (ISO zaman) öğelerine kalan süreyi, [data-ilerleme] çubuklarına oranı yazar.
// Süre dolunca "bitince" bir kez çağrılır (ör. veriyi tazelemek için). Dönen işlev sayacı durdurur.
function geriSay(kok, bitince) {
  let bitti = false;
  const adim = () => {
    const simdi = Date.now();
    let dolan = false;
    for (const el of $$("[data-bitis]", kok)) {
      const kalan = (Date.parse(el.dataset.bitis) - simdi) / 1000;
      el.textContent = kalan > 0 ? sure(kalan) : ç("bitti");
      if (kalan <= 0) dolan = true;
    }
    for (const el of $$("[data-ilerleme]", kok)) {
      const [bas, son] = el.dataset.ilerleme.split("|").map(Date.parse);
      el.style.width = Math.round(Math.max(0, Math.min(1, (simdi - bas) / (son - bas))) * 100) + "%";
    }
    if (dolan && !bitti && bitince) { bitti = true; setTimeout(bitince, 1500); }
  };
  adim();
  const t = setInterval(adim, 1000);
  return () => clearInterval(t);
}

// Ekran tazeleyici: aynı anda tek yükleme. Yükleme sürerken gelen istekler tek bir sonraki yüklemede birleşir; böylece
// geç gelen eski yanıt yeni veriyi ezmez (canlı olay ile kullanıcının işlemi aynı anda tazelediğinde).
function tazeleyici(is) {
  let calisan = null, tekrar = false;
  return async function tazele() {
    if (calisan) { tekrar = true; return calisan; }
    calisan = (async () => {
      do {
        tekrar = false;
        try { await is(); } catch (e) { tost(hataMetni(e), "circle-alert"); }
      } while (tekrar);
    })();
    try { await calisan; } finally { calisan = null; }
  };
}

// Süresi geçmiş aşama için tazeleme aralığı: sunucu aşamayı geç ilerletirse istekler seyrelir (4, 8, 16… en çok 60 sn).
function gecikmeli(sayac) {
  const ms = Math.min(60000, 4000 * 2 ** sayac.n);
  sayac.n++;
  return ms;
}

// Tarih ve saat (dilin biçimi, kısa).
const saatYaz = (iso) => new Date(iso).toLocaleString(DIL.yerel, { weekday: "short", day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });

// ===== 04_gorunus.js =====
// ---------- Görünüm (D-095; look-1.0.0): kayıtlı görünümler, profil resmi ve figürün ortak verisi ----------
// Görünüm: ten, saç rengi ve biçimi, sakal, yüz, beden silueti, kıyafet ve rengi, resmin zemini. Kaydetmemiş kişinin görünümü
// adından türetilir. Başkalarının kayıtlı görünümü gerektikçe topluca istenir (api.looks, en çok 100 kişi) ve oturum boyunca
// saklanır; gelince ekrandaki resimleri yerinde güncellenir. Görünüm süstür (D-070).

// Kural gelmeden de çizilebilsin diye look-1.0.0'ın seçenekleri (renkler 01_temel.js'teki dizilerle aynı).
const GORUNUS_VARSAYILAN_KURAL = veri({
  version: "look-1.0.0",
  skin: TEN, hairColor: SAC, outfitColors: GIYSI, backgrounds: ZEMIN,
  hairStyles: [{ id: "kisa", name: "Kısa" }, { id: "uzun", name: "Uzun" }, { id: "topuz", name: "Topuz" }, { id: "yan", name: "Yana taralı" },
    { id: "kirpik", name: "Kırpık" }, { id: "kivircik", name: "Kıvırcık" }, { id: "atkuyrugu", name: "At kuyruğu" }, { id: "kel", name: "Kel" }],
  beards: [{ id: "yok", name: "Yok" }, { id: "biyik", name: "Bıyık" }, { id: "sakal", name: "Sakal" }],
  faces: [{ id: "sakin", name: "Sakin" }, { id: "gulec", name: "Güleç" }, { id: "ciddi", name: "Ciddi" }, { id: "neseli", name: "Neşeli" },
    { id: "dalgin", name: "Dalgın" }, { id: "kararli", name: "Kararlı" }],
  bodies: [{ id: "ince", name: "İnce" }, { id: "orta", name: "Orta" }, { id: "iri", name: "İri" }],
  outfits: [{ id: "gunluk", name: "Günlük", uniform: false }, { id: "takim", name: "Takım elbise", uniform: false },
    { id: "tulum", name: "İş tulumu", uniform: false }, { id: "kazak", name: "Kazak", uniform: false }, { id: "spor", name: "Eşofman", uniform: false },
    { id: "yelek", name: "Yelek", uniform: false }, { id: "uniforma", name: "Üniforma", uniform: true }],
});
// Figürün kısa eylemleri (şartname §23: en az on): Görünüm ekranında denenir; şehir, eğitim, cephe ve sahne ekranları da
// aynı adlarla oynatır (49_figur3b.js).
const FIGUR_EYLEMLERI = [
  { id: "bekle", ad: ç("eylem::Bekle"), ik: "hourglass" }, { id: "selamla", ad: ç("eylem::Selamla"), ik: "hand" },
  { id: "calis", ad: ç("eylem::Çalış"), ik: "hammer" }, { id: "egit", ad: ç("eylem::Eğit"), ik: "dumbbell" },
  { id: "tasi", ad: ç("eylem::Taşı"), ik: "package" }, { id: "taarruz", ad: ç("eylem::Taarruz"), ik: "swords" },
  { id: "mevzi", ad: ç("eylem::Mevzi"), ik: "shield-half" }, { id: "kanat", ad: ç("eylem::Kanat"), ik: "move" },
  { id: "prova", ad: ç("eylem::Prova"), ik: "guitar" }, { id: "sahne", ad: ç("eylem::Sahne"), ik: "mic-vocal" },
];
const gorunusKurali = () => Durum.v.kurallar?.data?.look ?? GORUNUS_VARSAYILAN_KURAL;
// Üniformanın sabit renkleri
const UNIFORMA = { kumas: "#55603F", koyu: "#3A4230", kemer: "#3A2E22", sirma: "#E2B54A" };

// Addan türetilen görünüm: ten, renkler, saç ve sakal eski profil resminin seçimiyle birebir (aynı tohum ve sıra); yüz ve beden
// sonradan çekilir (eskiden tek yüz ve orta beden vardı).
function varsayilanGorunus(ad) {
  const r = rastgele(ozet(ad) ^ 0x9e3779b9);
  const i = (n) => Math.floor(r() * n);
  const K = GORUNUS_VARSAYILAN_KURAL;
  const ten = i(TEN.length), sacRenk = i(SAC.length), renk = i(GIYSI.length), zemin = i(ZEMIN.length);
  const stil = i(5);
  const sakal = stil !== 1 && stil !== 3 && r() < 0.28;
  const yuz = K.faces[i(K.faces.length)].id, beden = K.bodies[i(K.bodies.length)].id;
  return { ten, sacRenk, sac: K.hairStyles[stil].id, sakal: sakal ? "sakal" : "yok", yuz, beden, kiyafet: "gunluk", renk, zemin };
}

// Rütbe işaretinin biçimi (kuraldaki rütbe sayısına göre 12'lik ölçeğe çevrilir): 0–3 şerit, 4–7 yıldız, 8–10 yıldız ve
// defne, 11 dört yıldız ve çift defne (madalya vitrinindeki apoletle aynı, D-093).
function rutbeBicimi(sira, sayi = 12) {
  const i = Math.round((Math.max(0, sira) / Math.max(1, sayi - 1)) * 11);
  if (i <= 3) return { serit: i, yildiz: 0, defne: 0 };
  if (i <= 7) return { serit: 0, yildiz: i - 3, defne: 0 };
  return { serit: 0, yildiz: i === 11 ? 4 : i - 7, defne: i === 11 ? 2 : 1 };
}

const Gorunus = (() => {
  const onbellek = new Map(); // kimlik → { look, country_id, rank } ya da null (kaydetmemiş)
  const bekleyen = new Set();
  const dinleyici = new Set();
  let zaman = null;

  function iste(kimlikler) {
    for (const k of kimlikler) if (k && !onbellek.has(k)) bekleyen.add(k);
    if (bekleyen.size && !zaman) zaman = setTimeout(getir, 40);
  }
  async function getir() {
    zaman = null;
    const liste = [...bekleyen].slice(0, 100);
    for (const k of liste) bekleyen.delete(k);
    if (!liste.length) return;
    try {
      const r = await Sunucu.cagir("looks", { p_ids: liste });
      const bulunan = new Map((r ?? []).map((x) => [x.character_id, x]));
      for (const k of liste) onbellek.set(k, bulunan.get(k) ?? null);
    } catch {
      for (const k of liste) onbellek.set(k, null); // tekrar tekrar istenmesin; addan türetilen resim kalır
    }
    yay(liste);
    if (bekleyen.size) zaman = setTimeout(getir, 40);
  }
  function yay(kimlikler) {
    for (const k of kimlikler) {
      for (const el of document.querySelectorAll(`[data-avatar-kisi="${CSS.escape(k)}"]`)) el.innerHTML = avatarSvg(el.dataset.avatarAd ?? "", ...avatarSecim(k));
    }
    for (const f of dinleyici) { try { f(kimlikler); } catch (e) { console.error(e); } }
  }
  return {
    al: (k) => onbellek.get(k),
    iste,
    // Kendi kaydından sonra (ya da my_look ile) önbellek hemen güncellenir.
    yaz(k, kayit) { onbellek.set(k, kayit); yay([k]); },
    dinle(f) { dinleyici.add(f); return () => dinleyici.delete(f); },
    temizle() { onbellek.clear(); bekleyen.clear(); },
  };
})();

// Bir kişinin resmi için görünüm ve ek bilgi (üniformada ülke rengi ve rütbe); bilinmiyorsa addan türetilir.
function avatarSecim(kimlik) {
  const k = kimlik ? Gorunus.al(kimlik) : null;
  if (!k?.look) return [null, {}];
  return [k.look, { ulke: k.country_id, rutbe: k.rank }];
}

// Profil resmi kutusu: kimlik verilirse kayıtlı görünüm (gelince yerinde güncellenir), yoksa addan türetilen.
function avatarKutu(ad, kimlik) {
  if (kimlik) Gorunus.iste([kimlik]);
  return `<span class="avatar" aria-hidden="true"${kimlik ? ` data-avatar-kisi="${esc(kimlik)}" data-avatar-ad="${esc(ad)}"` : ""}>${avatarSvg(ad, ...avatarSecim(kimlik))}</span>`;
}

// Figürlerin ten ve saç rengi (meclis salonu): kayıtlı görünüm ya da addan türetilen (eski salonla aynı seçim).
function gorunusRenkleri(ad, kimlik) {
  if (kimlik) Gorunus.iste([kimlik]);
  const g = (kimlik && Gorunus.al(kimlik)?.look) || varsayilanGorunus(ad);
  const K = gorunusKurali();
  return [(K.skin ?? TEN)[g.ten] ?? TEN[0], (K.hairColor ?? SAC)[g.sacRenk] ?? SAC[0]];
}

// ===== 10_giris.js =====
// ---------- Giriş, kayıt, e-posta doğrulama, parola sıfırlama (D-015) ----------

const GirisEkrani = (() => {
  let yenidenGonderSon = 0;

  function sahne(icerik) {
    $("#uygulama").innerHTML = `
      <div class="giris-sahne">
        <picture>
          <source media="(max-width: 700px)" srcset="img/acilis_dikey.webp">
          <img src="img/acilis_yatay.webp" alt="" class="giris-resim">
        </picture>
        <section class="giris-kart">
          <div class="giris-logo"><img src="img/amblem.png" alt="" width="52" height="52"><div><small>${ç("ÇEVRİMİÇİ DÜNYA")}</small><b>CİVORA</b></div>
            <button class="baglanti dil-sec" id="dil-sec" type="button" lang="${DIL.kod === "tr" ? "en" : "tr"}">${DIL.kod === "tr" ? "English" : "Türkçe"}</button></div>
          ${icerik}
        </section>
      </div>`;
    // Dil: giriş ekranında da seçilebilir (bu cihazda saklanır; sayfa yeniden yüklenir)
    $("#dil-sec").onclick = () => DIL.ayarla(DIL.kod === "tr" ? "en" : "tr");
  }

  const kutu = (tur, metin) => metin ? `<div class="${tur === "hata" ? "hata-kutusu" : "bilgi-kutusu"}" role="${tur === "hata" ? "alert" : "status"}">
    ${ikon(tur === "hata" ? "circle-alert" : "info")}<span>${esc(metin)}</span></div>` : "";

  // Formu gönderirken düğmeyi kilitler, hatayı gösterir.
  function formBagla(sec, is) {
    const f = $(sec);
    f.addEventListener("submit", async (e) => {
      e.preventDefault();
      const d = $("button[type=submit]", f);
      const yer = $(".form-mesaj", f);
      d.disabled = true;
      yer.innerHTML = "";
      try {
        await is(new FormData(f), yer);
      } catch (err) {
        yer.innerHTML = kutu("hata", hataMetni(err));
      } finally {
        d.disabled = false;
      }
    });
  }

  const epostaGecerli = (e) => /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(e);

  function giris({ mesaj = "", hata = "" } = {}) {
    sahne(`
      <h1>${ç("Hoş geldin")}</h1>
      <p class="aciklama">${ç("Ülkeni kur, şehrini büyüt, tarihini birlikte yaz.")}</p>
      <form class="form" id="giris-form" novalidate>
        <label class="alan"><span>${ç("E-posta")}</span><input name="email" type="email" autocomplete="email" required inputmode="email"></label>
        <label class="alan"><span>${ç("Parola")}</span><input name="parola" type="password" autocomplete="current-password" required minlength="8"></label>
        <div class="form-mesaj">${kutu("hata", hata)}${kutu("bilgi", mesaj)}</div>
        <button class="dugme altin tam" type="submit">${ikon("key-round")}${ç("Giriş yap")}</button>
      </form>
      <div class="giris-alt">
        <button class="baglanti" id="kayit-git" type="button">${ç("Hesabın yok mu? Kayıt ol")}</button>
        <button class="baglanti" id="sifirla-git" type="button">${ç("Parolamı unuttum")}</button>
      </div>
      <p class="giris-dipnot"><a href="gizlilik.html">${ç("Gizlilik ve oyun kuralları")}</a></p>`);
    $("#kayit-git").onclick = () => kayit();
    $("#sifirla-git").onclick = () => sifirla();
    formBagla("#giris-form", async (v, yer) => {
      const email = String(v.get("email")).trim();
      if (!epostaGecerli(email)) { yer.innerHTML = kutu("hata", ç("E-posta adresini denetle.")); return; }
      try {
        await Sunucu.Giris.giris(email, String(v.get("parola")));
      } catch (e) {
        if (e.kod === "email_not_confirmed") return dogrula(email, ç("Önce e-postana gelen bağlantıya tıklayarak adresini doğrulamalısın."));
        throw e;
      }
      await Uygulama.oturumAcildi();
    });
    $("#giris-form input[name=email]").focus();
  }

  function kayit() {
    sahne(`
      <h1>${ç("Hesap aç")}</h1>
      <p class="aciklama">${ç("Ücretsiz. E-posta adresine bir doğrulama bağlantısı gelecek.")}</p>
      <form class="form" id="kayit-form" novalidate>
        <label class="alan"><span>${ç("E-posta")}</span><input name="email" type="email" autocomplete="email" required inputmode="email"></label>
        <label class="alan"><span>${ç("Parola")}</span><input name="parola" type="password" autocomplete="new-password" required minlength="8">
          <small>${ç("En az 8 karakter.")}</small></label>
        <label class="alan"><span>${ç("Parola (yeniden)")}</span><input name="parola2" type="password" autocomplete="new-password" required minlength="8"></label>
        <label class="onay"><input type="checkbox" name="yas" required><span>${ç("18 yaşından büyüğüm.")}</span></label>
        <label class="onay"><input type="checkbox" name="kural" required><span>${ç("<a>Gizlilik ve oyun kurallarını</a> okudum, kabul ediyorum.").replace("<a>", `<a href="gizlilik.html" target="_blank" rel="noopener">`)}</span></label>
        <div class="form-mesaj"></div>
        <button class="dugme altin tam" type="submit">${ikon("user-round-plus")}${ç("Kayıt ol")}</button>
      </form>
      <div class="giris-alt"><button class="baglanti" id="giris-git" type="button">${ç("Hesabın var mı? Giriş yap")}</button></div>`);
    $("#giris-git").onclick = () => giris();
    formBagla("#kayit-form", async (v, yer) => {
      const email = String(v.get("email")).trim();
      const p1 = String(v.get("parola")), p2 = String(v.get("parola2"));
      if (!epostaGecerli(email)) { yer.innerHTML = kutu("hata", ç("E-posta adresini denetle.")); return; }
      if (p1.length < 8) { yer.innerHTML = kutu("hata", ç("Parola en az 8 karakter olmalı.")); return; }
      if (p1 !== p2) { yer.innerHTML = kutu("hata", ç("İki parola aynı değil.")); return; }
      if (!v.get("yas") || !v.get("kural")) { yer.innerHTML = kutu("hata", ç("Devam etmek için iki onayı da işaretlemelisin.")); return; }
      const r = await Sunucu.Giris.kayit(email, p1);
      if (r.dogrulamaGerekli) return dogrula(email);
      await Uygulama.oturumAcildi();
    });
  }

  function dogrula(email, ust = "") {
    sahne(`
      <h1>${ç("E-postanı denetle")}</h1>
      <p class="aciklama">${ust ? esc(ust) + " " : ""}${ç("<b>{email}</b> adresine bir bağlantı gönderdik. Bağlantıya tıklayınca hesabın açılır ve oyuna dönersin.", { email: esc(email) })}</p>
      ${kutu("bilgi", ç("E-posta birkaç dakika içinde gelmezse istenmeyen (spam) klasörüne bak."))}
      <div class="form" style="margin-top:14px">
        <div class="form-mesaj" id="dogrula-mesaj"></div>
        <button class="dugme ikincil tam" id="yeniden-gonder" type="button">${ikon("send")}${ç("Bağlantıyı yeniden gönder")}</button>
      </div>
      <div class="giris-alt"><button class="baglanti" id="giris-git" type="button">${ç("Girişe dön")}</button></div>`);
    $("#giris-git").onclick = () => giris();
    $("#yeniden-gonder").onclick = async () => {
      const yer = $("#dogrula-mesaj");
      const kalan = 60 - Math.floor((Date.now() - yenidenGonderSon) / 1000);
      if (kalan > 0) { yer.innerHTML = kutu("bilgi", ç("Yeniden göndermek için {n} saniye bekle.", { n: kalan })); return; }
      try {
        await Sunucu.Giris.dogrulamaYenidenGonder(email);
        yenidenGonderSon = Date.now();
        yer.innerHTML = kutu("bilgi", ç("Bağlantı yeniden gönderildi."));
      } catch (e) {
        yer.innerHTML = kutu("hata", hataMetni(e));
      }
    };
  }

  function sifirla() {
    sahne(`
      <h1>${ç("Parolanı sıfırla")}</h1>
      <p class="aciklama">${ç("E-posta adresini yaz; parolanı değiştirmen için bir bağlantı gönderelim.")}</p>
      <form class="form" id="sifirla-form" novalidate>
        <label class="alan"><span>${ç("E-posta")}</span><input name="email" type="email" autocomplete="email" required inputmode="email"></label>
        <div class="form-mesaj"></div>
        <button class="dugme altin tam" type="submit">${ikon("send")}${ç("Bağlantı gönder")}</button>
      </form>
      <div class="giris-alt"><button class="baglanti" id="giris-git" type="button">${ç("Girişe dön")}</button></div>`);
    $("#giris-git").onclick = () => giris();
    formBagla("#sifirla-form", async (v, yer) => {
      const email = String(v.get("email")).trim();
      if (!epostaGecerli(email)) { yer.innerHTML = kutu("hata", ç("E-posta adresini denetle.")); return; }
      await Sunucu.Giris.sifirlamaIste(email);
      yer.innerHTML = kutu("bilgi", ç("Bu adresle bir hesap varsa bağlantı gönderildi. E-postanı denetle."));
    });
  }

  function yeniParola() {
    sahne(`
      <h1>${ç("Yeni parola")}</h1>
      <p class="aciklama">${ç("Hesabın için yeni bir parola belirle.")}</p>
      <form class="form" id="parola-form" novalidate>
        <label class="alan"><span>${ç("Yeni parola")}</span><input name="parola" type="password" autocomplete="new-password" required minlength="8">
          <small>${ç("En az 8 karakter.")}</small></label>
        <label class="alan"><span>${ç("Yeni parola (yeniden)")}</span><input name="parola2" type="password" autocomplete="new-password" required minlength="8"></label>
        <div class="form-mesaj"></div>
        <button class="dugme altin tam" type="submit">${ikon("lock")}${ç("Parolayı değiştir")}</button>
      </form>`);
    formBagla("#parola-form", async (v, yer) => {
      const p1 = String(v.get("parola")), p2 = String(v.get("parola2"));
      if (p1.length < 8) { yer.innerHTML = kutu("hata", ç("Parola en az 8 karakter olmalı.")); return; }
      if (p1 !== p2) { yer.innerHTML = kutu("hata", ç("İki parola aynı değil.")); return; }
      await Sunucu.Giris.parolaDegistir(p1);
      tost(ç("Parolan değiştirildi."), "lock");
      await Uygulama.oturumAcildi();
    });
  }

  return { giris, kayit, dogrula, sifirla, yeniParola };
})();

// ===== 11_karakter.js =====
// ---------- Karakter oluşturma (T-05; 172 ülke: D-100, D-101, D-103) ----------
// Açık ülkelerin hepsinden seçilir: dünya haritasından ya da aranabilen listeden. Öneri cihazın dilinden ve saat
// diliminden gelir (konum izni istenmez); bulunamazsa sunucunun yedek önerisi (uyanık ülkelerden vatandaşı az olan). Her
// ülkenin vatandaş ve etkin vatandaş sayısı, uyku durumu ve kalan kurucu yeri görünür.

// Dilin bölgesi yoksa, tek bir ülkeyle güçlü bağı olan diller (ör. Türkçe → Türkiye). Bölgeli dil etiketi ("en-GB") önce gelir.
const ULKE_DILI = { TUR: "tr", DEU: "de", FRA: "fr", ITA: "it", JPN: "ja", KOR: "ko", GRC: "el", POL: "pl", NLD: "nl", RUS: "ru",
  UKR: "uk", CZE: "cs", SVK: "sk", HUN: "hu", ROU: "ro", BGR: "bg", SRB: "sr", HRV: "hr", SVN: "sl", ALB: "sq", MKD: "mk",
  LTU: "lt", LVA: "lv", EST: "et", FIN: "fi", SWE: "sv", DNK: "da", NOR: "nb no nn", ISL: "is", ISR: "he", IRN: "fa", GEO: "ka",
  ARM: "hy", AZE: "az", KAZ: "kk", UZB: "uz", MNG: "mn", THA: "th", VNM: "vi", IDN: "id", MYS: "ms", KHM: "km", LAO: "lo",
  MMR: "my", NPL: "ne", LKA: "si", BGD: "bn", PAK: "ur", ETH: "am", TZA: "sw", CHN: "zh" };
const DIL_ULKE = new Map(Object.entries(ULKE_DILI).flatMap(([id, d]) => d.split(" ").map((x) => [x, id])));

// Önerilen ülke: dil bölgesi → başkentin saat dilimi (tek ülkeyse) → dil. Açık değilse öneri yok.
function ulkeOnerisi(acik) {
  const iso2 = new Map(Object.entries(DUNYA.ulkeler ?? {}).filter(([, u]) => u.iso2).map(([id, u]) => [u.iso2, id]));
  const diller = [...(navigator.languages ?? []), navigator.language].filter(Boolean).map(String);
  for (const d of diller) {
    const m = /^[a-z]{2,3}[-_]([a-z]{2})\b/i.exec(d);
    const id = m && iso2.get(m[1].toUpperCase());
    if (id && acik.has(id)) return id;
  }
  let tz = "";
  try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone ?? ""; } catch { /* eski tarayıcı */ }
  const tzUlke = Object.entries(DUNYA.ulkeler ?? {}).filter(([id, u]) => u.tz === tz && acik.has(id)).map(([id]) => id);
  if (tzUlke.length === 1) return tzUlke[0];
  for (const d of diller) {
    const id = DIL_ULKE.get(d.split(/[-_]/)[0].toLowerCase());   // "fil" Filipince, "fi" değil
    if (id && acik.has(id)) return id;
  }
  return null;
}

const KarakterEkrani = (() => {
  async function ac() {
    $("#uygulama").innerHTML = `<div class="giris-sahne"><picture><source media="(max-width: 700px)" srcset="img/acilis_dikey.webp">
      <img src="img/acilis_yatay.webp" alt="" class="giris-resim"></picture>
      <section class="giris-kart genis"><div class="yuk-kart">${ç("Ülkeler yükleniyor…")}</div></section></div>`;
    let s;
    try {
      s = await Sunucu.cagir("character_options");
    } catch (e) {
      $(".giris-kart").innerHTML = `<div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(e))}</span></div>
        <button class="dugme ikincil tam" style="margin-top:14px" id="yeniden">${ç("Yeniden dene")}</button>`;
      $("#yeniden").onclick = ac;
      return;
    }
    if (s.has_character) return Uygulama.oturumAcildi();
    const ulkeler = s.countries.map((c) => ({ ...c, ad: DUNYA.ulkeler?.[c.id]?.ad ?? c.name }));
    const byId = new Map(ulkeler.map((c) => [c.id, c]));
    const yerel = ulkeOnerisi(new Set(byId.keys()));
    const oneri = yerel ?? s.suggested ?? ulkeler[0]?.id ?? null;
    let secili = oneri;
    let arama = "";
    let suzgec = "hepsi";
    const esik = Number(s.dormancy?.minActiveCitizens ?? 5);
    const katla = (x) => x.toLocaleLowerCase(DIL.yerel).normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");   // aksansız arama

    const durumCip = (c) => c.awake ? `<span class="cip yesil">${ikon("sun")}${ç("Uyanık")}</span>`
      : `<span class="cip">${ikon("moon")}${ç("Uyuyan · {n}/{esik} etkin", { n: Number(c.active), esik })}</span>`;

    function seciliKart() {
      const c = byId.get(secili);
      if (!c) return `<p class="kucuk">${ç("Haritadan ya da listeden bir ülke seç.")}</p>`;
      return `<div class="ulke-secili-ust"><span class="ulke-bayrak" style="background:${ulkeRenk(c.id)}"></span>
          <b>${esc(c.ad)}</b>${durumCip(c)}</div>
        ${c.id === oneri ? `<p class="oneri-yazi">${ikon("sparkles")}${yerel ? ç("Dilinden ve saat diliminden önerildi") : ç("Önerilen")}</p>` : ""}
        <p class="kucuk">${ç("{n} vatandaş · {k} etkin", { n: Number(c.citizens), k: Number(c.active) })}${c.founders_left > 0
          ? " · " + ç("Kurucu Vatandaş Rozeti için {n} yer kaldı", { n: Number(c.founders_left) }) : ""}</p>
        <p class="kucuk">${c.awake ? ç("Uyanık ülkede seçimler ve savaş açık.")
          : ç("Uyuyan ülke: {esik} etkin vatandaşa ulaşınca uyanır ve Kurucu Meclis seçimi kendiliğinden başlar. Uyurken savaş açamaz, ona da savaş açılamaz.", { esik })}</p>`;
    }

    function liste() {
      const q = katla(arama.trim());
      const l = ulkeler.filter((c) => (suzgec === "hepsi" || (suzgec === "uyanik") === c.awake) && (!q || katla(c.ad).includes(q) || c.id.toLowerCase() === q))
        .sort((a, b) => (a.id === oneri ? -1 : b.id === oneri ? 1 : a.ad.localeCompare(b.ad, DIL.yerel)));
      if (!l.length) return `<p class="bos">${ç("Bu aramayla ülke bulunamadı.")}</p>`;
      return l.map((c) => `<button type="button" class="ulke-satir" data-ulke="${esc(c.id)}" aria-pressed="${c.id === secili}">
          <span class="ulke-nokta" style="background:${ulkeRenk(c.id)}"></span>
          <span class="ulke-satir-ad"><b>${esc(c.ad)}</b><span class="kucuk">${ç("{n} vatandaş · {k} etkin", { n: Number(c.citizens), k: Number(c.active) })}</span></span>
          ${c.id === oneri ? `<span class="cip altin">${ç("Önerilen")}</span>` : ""}
          ${c.awake ? `<span class="cip yesil">${ç("Uyanık")}</span>` : `<span class="cip">${ç("Uyuyan")}</span>`}
        </button>`).join("");
    }

    $(".giris-kart").innerHTML = `
      <div class="giris-logo"><img src="img/amblem.png" alt="" width="52" height="52"><div><small>${ç("ÇEVRİMİÇİ DÜNYA")}</small><b>CİVORA</b></div></div>
      <h1>${ç("Karakterini oluştur")}</h1>
      <p class="aciklama">${ç("Adın oyunda herkese görünür. Ülken, oy vereceğin ve uğruna savaşacağın yerdir; dünyadaki bütün ülkeler açık, istediğini seç. Sonra değiştirebilirsin ama savaş sırasında beklemen gerekir.")}</p>
      <form class="form" id="karakter-form" novalidate>
        <label class="alan"><span>${ç("Karakter adı")}</span><input name="ad" required minlength="${s.name.min}" maxlength="${s.name.max}" autocomplete="nickname" autocapitalize="words">
          <small>${ç("{min}–{max} karakter. Gerçek adını yazmak zorunda değilsin.", { min: s.name.min, max: s.name.max })}</small></label>
        <div class="alan"><span>${ç("Ülke")}</span>
          <div class="ulke-secili" id="ulke-secili" aria-live="polite">${seciliKart()}</div>
          <div class="ulke-harita" id="ulke-harita"><p class="kucuk">${ç("Harita yükleniyor…")}</p></div>
          <input type="search" id="ulke-ara" placeholder="${ç("Ülke ara")}" aria-label="${ç("Ülke ara")}" autocomplete="off">
          <div class="secim-sec" id="ulke-suzgec" role="group" aria-label="${ç("Ülkeleri süz")}">
            <button type="button" class="secim-cip" data-suzgec="hepsi" aria-pressed="true">${ç("Hepsi · {n}", { n: ulkeler.length })}</button>
            <button type="button" class="secim-cip" data-suzgec="uyanik" aria-pressed="false">${ç("Uyanık · {n}", { n: ulkeler.filter((c) => c.awake).length })}</button>
            <button type="button" class="secim-cip" data-suzgec="uyuyan" aria-pressed="false">${ç("Uyuyan · {n}", { n: ulkeler.filter((c) => !c.awake).length })}</button>
          </div>
          <div class="ulke-liste" id="ulkeler">${liste()}</div>
          <small>${ç("Uyuyan ülke: {esik} etkin vatandaştan azı olan ülke. Bir ülkenin ilk 50 vatandaşı kalıcı Kurucu Vatandaş Rozeti alır.", { esik })}</small></div>
        <div class="form-mesaj"></div>
        <button class="dugme altin tam" type="submit">${ikon("sparkles")}${ç("Karakteri aç")}</button>
      </form>
      <div class="giris-alt"><button class="baglanti" id="cikis" type="button">${ç("Çıkış yap")}</button></div>`;

    // Dünya haritası (hafif SVG; ülke şekilleri harita verisinden). Uyanık ülke kendi renginde, uyuyan soluk, seçili çizgili.
    let haritaHazir = false;
    function haritaCiz() {
      const kutu = $("#ulke-harita");
      if (!kutu || !haritaHazir) return;
      for (const p of $$("[data-ulke]", kutu)) {
        const c = byId.get(p.dataset.ulke);
        p.setAttribute("fill", c ? (c.awake ? ulkeRenk(c.id) : renkKaristir(ulkeRenk(c.id), "#EDE6D4", 0.55)) : "#DCD5C4");
        p.classList.toggle("secili", p.dataset.ulke === secili);
      }
      $("[data-ulke].secili", kutu)?.parentNode.appendChild($("[data-ulke].secili", kutu)); // seçili üstte
    }
    haritaVerisi().then((veri) => {
      const y = yollar2b(veri);
      const [w, h] = veri.tuval?.length === 2 && veri.tuval[0] > 100 ? veri.tuval : [2000, 870];
      const kutu = $("#ulke-harita");
      if (!kutu) return;
      kutu.innerHTML = `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${ç("Dünya haritası: ülke seçmek için dokun")}">
        <path d="${y.notr}" class="notr2b"/>
        ${veri.ulkeler.filter((u) => y.ulke.has(u.id)).map((u) => `<path data-ulke="${esc(u.id)}" d="${y.ulke.get(u.id)}"${byId.has(u.id)
          ? ` role="button" aria-label="${esc(byId.get(u.id).ad)}"` : ""}><title>${esc(byId.get(u.id)?.ad ?? u.ad)}</title></path>`).join("")}
      </svg>`;
      haritaHazir = true;
      haritaCiz();
    }).catch(() => { const k = $("#ulke-harita"); if (k) k.innerHTML = `<p class="kucuk">${ç("Harita yüklenemedi; listeden seçebilirsin.")}</p>`; });

    function sec(id) {
      if (!byId.has(id)) return;
      secili = id;
      $("#ulke-secili").innerHTML = seciliKart();
      for (const x of $$("#ulkeler [data-ulke]")) x.setAttribute("aria-pressed", String(x.dataset.ulke === secili));
      haritaCiz();
    }
    $("#ulke-harita").addEventListener("click", (e) => { const p = e.target.closest("[data-ulke]"); if (p) sec(p.dataset.ulke); });
    $("#ulkeler").addEventListener("click", (e) => { const b = e.target.closest("[data-ulke]"); if (b) sec(b.dataset.ulke); });
    $("#ulke-ara").addEventListener("input", (e) => { arama = e.target.value; $("#ulkeler").innerHTML = liste(); });
    $("#ulke-suzgec").addEventListener("click", (e) => {
      const b = e.target.closest("[data-suzgec]");
      if (!b) return;
      suzgec = b.dataset.suzgec;
      for (const x of $$("#ulke-suzgec [data-suzgec]")) x.setAttribute("aria-pressed", String(x === b));
      $("#ulkeler").innerHTML = liste();
    });
    $("#cikis").onclick = () => Uygulama.cikis();
    $("#karakter-form").addEventListener("submit", async (e) => {
      e.preventDefault();
      const ad = String(new FormData(e.target).get("ad") ?? "").trim().replace(/\s+/g, " ");
      const yer = $(".form-mesaj");
      const d = $("button[type=submit]", e.target);
      if (ad.length < s.name.min || ad.length > s.name.max) {
        yer.innerHTML = `<div class="hata-kutusu">${ikon("circle-alert")}<span>${ç("Ad {min}–{max} karakter olmalı.", { min: s.name.min, max: s.name.max })}</span></div>`;
        return;
      }
      if (!secili) {
        yer.innerHTML = `<div class="hata-kutusu">${ikon("circle-alert")}<span>${ç("Bir ülke seç.")}</span></div>`;
        return;
      }
      d.disabled = true;
      try {
        await Sunucu.cagir("character_create", { p_name: ad, p_country_id: secili });
        // Topluluk kuralları kayıtta onaylandı (kayıt formundaki zorunlu kutu); karakter için de kaydedilir (sohbet, parti).
        await Sunucu.cagir("chat_accept_terms").catch(() => {});
        tost(ç("Karakterin açıldı. Başlangıç paketin çantanda!"), "party-popper");
        await Uygulama.oturumAcildi();
      } catch (err) {
        yer.innerHTML = `<div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(err))}</span></div>`;
        d.disabled = false;
      }
    });
    $("#karakter-form input[name=ad]").focus();
  }
  return { ac };
})();

// ===== 20_kabuk.js =====
// ---------- Uygulama kabuğu: üst bant, bölümler ve alt sekmeler, yönlendirme ----------
// Bilgi düzeni arayüz önizlemesiyle aynı (D-062): Dünya, Şehrim, Ülkem, Meydan, Hayatım; her bölümün alt sekmeleri.
// Masaüstünde bölümler üstte, telefonda altta. Adres çubuğunda #bölüm/alt (ör. #sehir/pazar).

const Kabuk = (() => {
  // Bir bölüm ancak en az bir alt ekranı kayıtlıysa görünür (henüz bağlanmamış bölüm gösterilmez).
  const BOLUMLER = [
    { id: "dunya", ad: ç("Dünya"), ik: "globe", alt: [["harita", ç("Harita"), "globe"]] },
    { id: "sehir", ad: ç("Şehrim"), ik: "building", alt: [["sehir", ç("Şehir"), "castle"], ["is", ç("Çalış"), "briefcase-business"], ["uretim", ç("Üretim"), "factory"],
      ["pazar", ç("Pazar"), "store"], ["ev", ç("Evim"), "house"], ["yol", ç("Seyahat"), "route"], ["golge", ç("Gölge"), "moon-star"]] },
    { id: "ulke", ad: ç("Ülkem"), ik: "landmark", alt: [["ozet", ç("Özet"), "landmark"], ["meclis", ç("Meclis"), "gavel"], ["secim", ç("Seçim"), "vote"], ["cephe", ç("Cephe"), "swords"],
      ["diplomasi", ç("Diplomasi"), "handshake"]] },
    { id: "meydan", ad: ç("Meydan"), ik: "message-circle", alt: [["akis", ç("Akış"), "megaphone"], ["sohbet", ç("Sohbet"), "message-circle"], ["arkadas", ç("Arkadaşlar"), "users-round"]] },
    { id: "hayat", ad: ç("Hayatım"), ik: "user-round", alt: [["profil", ç("Profil"), "user-round"], ["gorunum", ç("Görünüm"), "shirt"], ["egitim", ç("Eğitim"), "graduation-cap"],
      ["ayarlar", ç("Ayarlar"), "settings"]] },
  ];
  const VARSAYILAN = "hayat/profil";
  const ekranlar = {};
  let etkin = null;
  let birak = null;
  let kurulu = false;

  const kaydet = (rota, ekran) => { ekranlar[rota] = ekran; };
  const bolumler = () => BOLUMLER.map((b) => ({ ...b, alt: b.alt.filter(([a]) => ekranlar[`${b.id}/${a}`]) })).filter((b) => b.alt.length);

  function kur() {
    kurulu = true;
    const bs = bolumler();
    $("#uygulama").innerHTML = `
      <header class="ust">
        <div class="ust-ic">
          <a class="logo" href="#${VARSAYILAN}" aria-label="${ç("Civora, ana sayfa")}">
            <span class="logo-kutu"><img src="img/amblem.png" alt="" width="34" height="34"></span>
            <span class="logo-yazi"><small>${ç("ÇEVRİMİÇİ DÜNYA")}</small><b>CİVORA</b></span>
          </a>
          <div class="ust-degerler" id="ust-degerler"></div>
          <div class="ust-sag">
            <span class="canli-nokta" id="canli-nokta" title="${ç("Canlı bağlantı")}" style="opacity:.25"></span>
            <button class="oyuncu-cip" id="oyuncu-cip" type="button"></button>
          </div>
        </div>
      </header>
      <nav class="sekmeler" aria-label="${ç("Ana bölümler")}"><div class="sekmeler-ic" id="sekmeler">${bs.map((b) =>
        `<button class="sekme" data-bolum="${b.id}">${ikon(b.ik)}<span>${esc(b.ad)}</span></button>`).join("")}</div></nav>
      <main class="icerik"><div class="sayfa altsekme-sayfa" id="altsekmeler-yer"></div><div id="icerik"></div></main>
      <nav class="alt-sekmeler" id="alt-sekmeler" aria-label="${ç("Ana bölümler")}">${bs.map((b) =>
        `<button data-bolum="${b.id}">${ikon(b.ik)}<span>${esc(b.ad)}</span></button>`).join("")}</nav>`;
    for (const nav of [$("#sekmeler"), $("#alt-sekmeler")]) {
      nav.addEventListener("click", (e) => {
        const d = e.target.closest("[data-bolum]");
        if (!d) return;
        const b = bs.find((x) => x.id === d.dataset.bolum);
        git(`${b.id}/${b.alt[0][0]}`);
      });
    }
    $("#altsekmeler-yer").addEventListener("click", (e) => { const d = e.target.closest("[data-rota]"); if (d) git(d.dataset.rota); });
    $("#oyuncu-cip").onclick = () => git("hayat/profil");
    Durum.dinle("ozet", ustGuncelle);
    Durum.dinle("askerlik", ustGuncelle);
    Gorunus.dinle((k) => { if (k.includes(Durum.v.ozet?.character?.id)) ustGuncelle(); });
    Sunucu.Canli.durum((b) => { const n = $("#canli-nokta"); if (n) n.style.opacity = b ? "1" : ".25"; });
    addEventListener("hashchange", () => { const r = location.hash.slice(1); if (ekranlar[r] && r !== etkin) git(r, { gecmis: false }); });
    ustGuncelle();
  }

  // Gözaltı (D-097): bitiş saatine kadar üst bantta görünür, dokununca Gölge ekranı; süre dolunca kendiliğinden kalkar.
  let gozaltiZaman = null;
  function gozaltiCipi(o) {
    clearTimeout(gozaltiZaman);
    const bitis = Date.parse(o.character?.detained_until ?? "");
    if (!(bitis > Date.now())) return "";
    gozaltiZaman = setTimeout(ustGuncelle, Math.min(bitis - Date.now() + 1000, 2 ** 31 - 1));
    const saat = new Date(bitis).toLocaleTimeString(DIL.yerel, { hour: "2-digit", minute: "2-digit" });
    return `<span class="deger-ayrac"></span><a class="deger d-gozalti" href="#sehir/golge" title="${ç("Gözaltındasın; dokununca ayrıntı")}">${ikon("lock")}<span><span class="deger-sayi">${esc(saat)}</span><span class="deger-ad"> ${ç("gözaltı")}</span></span></a>`;
  }

  function ustGuncelle() {
    const o = Durum.v.ozet, a = Durum.v.askerlik;
    if (!o || !$("#ust-degerler")) return;
    const kredi = o.balances?.find((b) => b.asset === "CR")?.spendable ?? 0;
    const s = a?.soldier;
    $("#ust-degerler").innerHTML = `
      <div class="deger" title="${ç("Kredi")}">${ikon("coins")}<span><span class="deger-sayi">${kr(kredi)}</span><span class="deger-ad"> ${ç("kr")}</span></span></div>
      <span class="deger-ayrac"></span>
      <div class="deger" title="${ç("Enerji")}">${ikon("zap")}<span><span class="deger-sayi">${s ? sayi(s.energy) : "—"}</span><span class="deger-ad">${s ? " / " + sayi(s.energy_max) : ""}</span></span></div>
      <span class="deger-ayrac"></span>
      <div class="deger d-erzak" title="${ç("Erzak")}">${ikon("croissant")}<span><span class="deger-sayi">${sayi(Durum.stok("erzak@1"))}</span></span></div>${gozaltiCipi(o)}`;
    const ad = o.character?.name ?? "";
    if (o.character?.id) Gorunus.iste([o.character.id]);
    $("#oyuncu-cip").innerHTML = `<span class="avatar" aria-hidden="true">${avatarSvg(ad, ...avatarSecim(o.character?.id))}</span>
      <span><span class="kabuk-ust-ad">${esc(ad)}</span><br><span class="kabuk-ust-alt">${esc(s ? ç("{n}. seviye · {r}", { n: Number(s.level), r: çv(s.rank_name) }) : "")}</span></span>`;
  }

  // Her ekran kendi kabını alır: ekrandan çıkınca kap belgeden ayrılır; eski ekranın geciken bir tazelemesi (zamanlayıcı,
  // yanıtı geç gelen istek) artık görünen ekranı ezemez. Yüklenirken çıkılan ekranın bırakma işlevi hemen çağrılır.
  let nesil = 0;
  async function git(rota, { gecmis = true } = {}) {
    if (!kurulu) kur();
    if (!ekranlar[rota]) rota = VARSAYILAN;
    if (birak) { try { birak(); } catch (e) { console.error(e); } birak = null; }
    const benim = ++nesil;
    etkin = rota;
    const [bolum] = rota.split("/");
    const b = bolumler().find((x) => x.id === bolum);
    for (const d of $$("[data-bolum]")) d.setAttribute("aria-current", d.dataset.bolum === bolum ? "page" : "false");
    $("#altsekmeler-yer").innerHTML = b && b.alt.length > 1 ? `<div class="altsekmeler" role="tablist">${b.alt.map(([a, ad, ik]) =>
      `<button class="altsekme" data-rota="${bolum}/${a}" aria-pressed="${rota === `${bolum}/${a}`}">${ikon(ik)}${esc(ad)}</button>`).join("")}</div>` : "";
    if (gecmis && location.hash.slice(1) !== rota) history.pushState(null, "", "#" + rota);
    const kap = document.createElement("div");
    kap.className = "ekran";
    kap.innerHTML = `<div class="sayfa"><div class="kart yuk-kart">${ç("Yükleniyor…")}</div></div>`;
    $("#icerik").replaceChildren(kap);
    window.scrollTo(0, 0);
    try {
      const cik = (await ekranlar[rota].ac(kap)) ?? null;
      if (benim !== nesil) { try { cik?.(); } catch (e) { console.error(e); } return; }
      birak = cik;
    } catch (e) {
      if (benim !== nesil) return;
      console.error(e);
      kap.innerHTML = `<div class="sayfa"><div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(e))}</span></div>
        <button class="dugme ikincil" style="margin-top:14px" id="ekran-yenile">${ç("Yeniden dene")}</button></div>`;
      $("#ekran-yenile", kap).onclick = () => git(rota, { gecmis: false });
    }
  }

  return { kaydet, git, kur, ustGuncelle, VARSAYILAN, get etkin() { return etkin; }, sifirla() { kurulu = false; etkin = null; } };
})();

// ===== 21_ozet.js =====
// ---------- Hayatım: karakter, asker kartı, çanta, ilk adımlar, vitrin (rütbe ve madalyalar; D-093) ----------

const varlikAdi = (asset) => {
  const [urun, q] = String(asset).split("@");
  const u = URUN[urun];
  const ad = u?.ad ?? urun;
  return urun === "techizat" ? ç("{q}. kalite silah", { q: Number(q) }) : Number(q) > 1 ? ç("{ad} ({q}. kalite)", { ad, q: Number(q) }) : ad;
};
const varlikResim = (asset) => {
  const urun = String(asset).split("@")[0];
  return URUN[urun] ? urunResim(urun) : "img/amblem.png";
};

Kabuk.kaydet("hayat/profil", {
  async ac(kap) {
    let is = null, secim = null, madalya = null;
    const vitrin = Vitrin.ac(); // rütbe ve madalya vitrini (D-093); yeniden çizimde aynı kart yerine konur
    await Promise.all([Durum.ozet(), Durum.askerlik(), Sunucu.cagir("my_work").then((x) => { is = x; }).catch(() => {}),
      Sunucu.cagir("election_status").then((x) => { secim = x?.election ?? null; }).catch(() => {}),
      Sunucu.cagir("medals").then((x) => { madalya = x; }).catch(() => {})]);
    const ciz = () => {
      const o = Durum.v.ozet, a = Durum.v.askerlik;
      const s = a?.soldier;
      const ch = o.character;
      const stoklar = (o.balances ?? []).filter((b) => b.asset !== "CR" && b.amount > 0);
      const kredi = o.balances?.find((b) => b.asset === "CR")?.spendable ?? 0;
      const xpOran = s && s.next_level_xp ? (s.xp - s.level_xp) / (s.next_level_xp - s.level_xp) : 1;
      const donmaOnce = secim?.stage === "scheduled" && Date.parse(secim.freeze_at) > Date.now();
      const adimlar = [
        { bitti: a?.basic_training_done, ik: "target", ad: ç("Temel askerî eğitimi bitir"), aciklama: ç("Tatbikatta botla dokunarak vurmayı öğren; bir şey kaybetmezsin."), git: "ulke/cephe" },
        { bitti: !!ch.civic_tutorial_done, ik: "vote", ad: ç("Vatandaşlık öğreticisini bitir"),
          aciklama: donmaOnce ? ç("Seçimde oy vermek için şart. Seçmen listesinin donma zamanı: {zaman}.", { zaman: saatYaz(secim.freeze_at) })
            : ç("Seçimlerde oy vermek için şart; birkaç dakika sürer."),
          is: () => vatandaslikOgreticisi() },
        { bitti: !!(is && (is.units_today > 0 || is.active || is.recent?.length)), ik: "briefcase-business", ad: ç("İlk işini yap"),
          aciklama: ç("Sistem işinde çalış: ücret ve günlük erzak tayını kazan."), git: "sehir/is" },
        ...(ch.terms_accepted ? [] : [{ bitti: false, ik: "scroll-text", ad: ç("Topluluk kurallarını kabul et"),
          aciklama: ç("Sohbet, parti ve paylaşım için gerekli."), is: () => kurallariKabul() }]),
        { bitti: false, ik: "store", ad: ç("Pazara bak"), aciklama: ç("Erzak, mühimmat ve silah fiyatlarını gör; çantandakini sat."), git: "sehir/pazar", ikincil: true },
      ];
      kap.innerHTML = `
        <div class="sayfa sayfa-dar">
          <div class="sayfa-bas"><div>
            <p class="ust-yazi">${ç("{ulke} vatandaşı · {yer}", { ulke: esc(ulkeAdi(ch.citizenship)), yer: esc(bolgeAdi(ch.location)) })}</p>
            <h1 class="b1">${esc(ch.name)}</h1>
            <p class="aciklama">${ç("Kasanda <b>{kr} kredi</b> var.", { kr: kr(kredi) })} ${a?.live_war ? ç("Ülkenin süren bir savaşı var; Cephe'ye bak.") : ç("Şu an ülkenin süren bir savaşı yok.")}</p>
          </div></div>
          <div class="izgara iki">
            <div class="yigin">
              ${adimlar.some((x) => !x.bitti && !x.ikincil) ? `<section class="kart"><div class="kart-bas"><div><p class="ust-yazi">${ç("İlk adımlar")}</p><h2 class="b2">${ç("Nereden başlamalı?")}</h2></div></div>
                <ol class="ilk-adimlar">${adimlar.map((x, i) => `<li class="ilk-adim ${x.bitti ? "bitti" : ""}">
                  <span class="ozet-ikon" style="background:var(--orman-acik);color:var(--orman)">${ikon(x.bitti ? "check" : x.ik)}</span>
                  <span><b>${esc(x.ad)}</b><span class="kucuk">${esc(x.aciklama)}</span></span>
                  ${x.bitti ? "" : x.is ? `<button class="dugme kucuk-d" data-adim="${i}">${ç("Başla")}</button>` : `<button class="dugme kucuk-d" data-git="${x.git}">${ç("Başla")}</button>`}</li>`).join("")}</ol></section>` : ""}
              <section class="kart">
                <div class="kart-bas"><div><p class="ust-yazi">${ç("Asker kartı")}</p><h2 class="b2">${s ? ç("{r} · {n}. seviye", { r: esc(çv(s.rank_name)), n: Number(s.level) }) : ç("Henüz cepheye çıkmadın")}</h2></div>
                  <span class="ik-kutu">${ikon("shield")}</span></div>
                ${s ? `
                <div class="asker-satir">
                  <div class="asker-deger"><b>${sayi(s.energy)}<small class="kucuk"> / ${sayi(s.energy_max)}</small></b><span>${ç("Enerji (vuruş başı {n})", { n: Number(s.per_hit) })}</span></div>
                  <div class="asker-deger"><b>${puan(s.power)}</b><span>${ç("Vuruş gücü (puan)")}</span></div>
                  <div class="asker-deger"><b>${s.best_quality ? ç("{q}. kalite", { q: Number(s.best_quality) }) : ç("Silahsız")}</b><span>${ç("Silah")}</span></div>
                  <div class="asker-deger"><b>${sayi(s.supplies.ammo)}</b><span>${ç("Mühimmat")}</span></div>
                </div>
                <div style="margin-top:14px"><div class="satir" style="justify-content:space-between"><span class="kucuk">${ç("Deneyim: {xp}", { xp: sayi(s.xp) + (s.next_level_xp ? " / " + sayi(s.next_level_xp) : "") })}</span>
                  <span class="kucuk">${ç("Askerlik becerisi {n}", { n: Number(s.skill) })}</span></div>
                  <div class="cubuk" style="margin-top:6px"><i style="display:block;height:100%;width:${Math.round(Math.max(0, Math.min(1, xpOran)) * 100)}%;background:var(--altin)"></i></div></div>` : ""}
              </section>
            </div>
            <section class="kart">
              <div class="kart-bas"><div><p class="ust-yazi">${ç("Çanta")}</p><h2 class="b2">${ç("Stoğun")}</h2></div><span class="ik-kutu">${ikon("package")}</span></div>
              ${stoklar.length ? `<div class="stok-izgara">${stoklar.map((b) => `<div class="stok"><img src="${varlikResim(b.asset)}" alt="">
                <span><b>${sayi(b.spendable)}</b><span>${esc(varlikAdi(b.asset))}${b.held ? " · " + ç("{n} ayrılmış", { n: Number(b.held) }) : ""}</span></span></div>`).join("")}</div>`
                : `<p class="bos">${ç("Çantan boş.")}</p>`}
            </section>
          </div>
          ${madalya ? `<div id="vitrin-yer"></div>` : ""}
        </div>`;
      if (madalya) { $("#vitrin-yer", kap)?.replaceWith(vitrin.el); vitrin.yaz({ madalya, asker: s ?? null }); }
      for (const b of $$("[data-git]", kap)) b.onclick = () => Kabuk.git(b.dataset.git);
      for (const b of $$("[data-adim]", kap)) b.onclick = () => adimlar[Number(b.dataset.adim)].is();
    };
    ciz();
    const b1 = Durum.dinle("ozet", ciz), b2 = Durum.dinle("askerlik", ciz);
    return () => { b1(); b2(); vitrin.kapat(); };
  },
});

// Topluluk kuralları (gizlilik.html'deki "Oyun kuralları"nın özeti): sohbet, parti ve paylaşım için bir kez kabul edilir.
function kurallariKabul() {
  pencere({ ust: ç("Topluluk"), baslik: ç("Topluluk kuralları"),
    govde: `<ul class="kural-listesi">
        <li>${ç("Herkese saygılı ol: hakaret, taciz, nefret söylemi ve cinsel içerik yasaktır.")}</li>
        <li>${ç("Kişi başına tek hesap. Birden çok hesapla oy vermek ya da savaşmak yasaktır.")}</li>
        <li>${ç("Hile, açık kullanma ve otomatik dokunma programları yasaktır. Bir hata bulursan kullanma, bildir.")}</li>
        <li>${ç("Kurallara uymayan mesaj ve paylaşımlar gizlenebilir; hesap kısıtlanabilir.")}</li>
      </ul><p class="kucuk"><a href="gizlilik.html" target="_blank" rel="noopener">${ç("Gizlilik ve oyun kurallarının tamamı")}</a></p>`,
    dugmeler: [{ ad: ç("Sonra") }, { ad: ç("Kabul ediyorum"), sinif: "altin", is: async () => {
      try { await Sunucu.cagir("chat_accept_terms"); await Durum.ozet(); tost(ç("Topluluk kurallarını kabul ettin."), "badge-check"); }
      catch (e) { tost(hataMetni(e), "circle-alert"); }
    } }] });
}

// Güç mili-puan cinsindendir (1,00 puan = 100.000; D-069).
const puan = (milli) => (Number(milli) / 100000).toLocaleString(DIL.yerel, { maximumFractionDigits: 1 });
// Ülke ve bölge adı: dünya verisinden (İngilizcede İngilizce adı; 00_dil.js)
const ulkeAdi = (id) => DUNYA.ulkeler?.[id]?.ad ?? id;
const bolgeAdi = (id) => DUNYA.bolgeler?.[id]?.ad ?? id;

// ===== 22_cephe.js =====
// ---------- Cephe: vuruşlu tatbikat (D-072) ve ülkenin savaşları ----------
// Tatbikat gerçek cepheyle aynı usul: kesim, duruş ve 1–10 vuruş (dokunarak). Bot gerçek rakip gibi sunulmaz (§05).

const KESIM = { left: { ad: ç("Sol kanat"), agirlik: 3 }, center: { ad: ç("Merkez"), agirlik: 4 }, right: { ad: ç("Sağ kanat"), agirlik: 3 } };
const DURUS = {
  assault: { ad: ç("Taarruz"), yener: ç("Mevziyi yener") },
  hold: { ad: ç("Mevzi"), yener: ç("Yan manevrayı yener") },
  flank: { ad: ç("Yan manevra"), yener: ç("Taarruzu yener") },
};
const payYuzde = (ppm) => ç("%{n}", { n: Math.round(Number(ppm) / 10000) });

Kabuk.kaydet("ulke/cephe", {
  async ac(kap) {
    let a = await Durum.askerlik();
    let oturum = null;              // açık tatbikat (drill_json)
    let sonuc = null;               // son adımın yanıtı
    let secim = { kesim: "center", durus: "assault", vurus: 0 };
    let gonderiliyor = false;
    let bitis = null;

    const tatbikatKarti = () => {
      const d = a.drill;
      const hak = d.daily_limit - d.sessions_last_24h;
      if (oturum) return adimKarti();
      return `<section class="kart">
        <div class="kart-bas"><div><p class="ust-yazi">${ç("Tatbikat cephesi · bota karşı")}</p><h2 class="b2">${ç("Vurmayı öğren")}</h2></div><span class="ik-kutu">${ikon("target")}</span></div>
        <p class="aciklama">${ç("Beş adımlık kısa bir çatışma. Her adımda bir kesim ve duruş seçip en çok 10 kez vurursun; gücün gerçek cephedeki gibi hesaplanır. Tatbikat malına, enerjine ve deneyimine dokunmaz.")}${a.basic_training_done ? "" : " " + ç("İlk tatbikatı bitirince gerçek cepheye katılabilirsin.")}</p>
        ${bitis ? bitisKutusu() : ""}
        <div class="satir" style="margin-top:14px;flex-wrap:wrap">
          <button class="dugme altin" id="tb-basla" ${hak <= 0 ? "disabled" : ""}>${ikon("play")}${d.open_session_id ? ç("Tatbikata devam et") : ç("Tatbikatı başlat")}</button>
          <span class="kucuk">${ç("Bugün kalan hak: {kalan} / {toplam}", { kalan: Math.max(0, hak), toplam: Number(d.daily_limit) })}</span>
        </div>
      </section>`;
    };

    const bitisKutusu = () => `<div class="${bitis.won ? "bilgi-kutusu" : "hata-kutusu"}" style="margin-top:12px">${ikon(bitis.won ? "trophy" : "circle-alert")}
      <span>${bitis.won ? ç("Tatbikatı kazandın!") : ç("Bu tatbikatı bot kazandı; bir daha dene.")} ${ç("Ortalama pay: <b>{pay}</b>.", { pay: payYuzde(bitis.total_x10 / bitis.steps_total / 10) })}
      ${bitis.ilk ? ç("Temel askerî eğitimin tamamlandı: artık gerçek cepheye katılabilirsin.") : ""}</span></div>`;

    const adimKarti = () => {
      const s = a.soldier;
      const dusman = new Map((oturum.next_enemy ?? []).map((e) => [e.sector, e]));
      const plan = oturum.mode !== "hits";
      const adimlar = Array.from({ length: oturum.steps_total }, (_, i) => {
        const r = sonucGecmisi[i];
        return `<i class="${r ? (r > 5_000_000 ? "kazandi" : "kaybetti") : i === oturum.steps_done ? "simdi" : ""}"></i>`;
      }).join("");
      return `<section class="kart" aria-live="polite">
        <div class="tb-ust"><div><p class="ust-yazi">${ç("Tatbikat · adım {n} / {toplam}", { n: oturum.steps_done + 1, toplam: oturum.steps_total })}</p><h2 class="b2">${sonuc ? ç("Adımın sonucu") : ç("Kesimini ve duruşunu seç")}</h2></div>
          <div class="tb-adimlar" aria-hidden="true">${adimlar}</div></div>
        ${sonuc ? sonucKutusu() : `
        <p class="kucuk" style="margin:10px 0 8px">${ç("Kesim (ağırlık: sol 3, merkez 4, sağ 3). Düşmanın nerede toplandığı canlı çubukta görünür; duruşunu adımdan sonra görürsün.")}</p>
        <div class="tb-kesimler" role="group" aria-label="${ç("Kesim")}">${Object.entries(KESIM).map(([k, x]) => {
          const e = dusman.get(k);
          return `<button class="tb-kesim" data-kesim="${k}" aria-pressed="${secim.kesim === k}"><b>${x.ad}</b><span class="agirlik">${ç("Ağırlık {n}", { n: x.agirlik })}</span>
            ${e ? `<span class="tb-dusman">${ç("Düşman: {n} vuruş · {puan} puan", { n: Number(e.hits), puan: puan(e.power) })}</span>` : `<span class="tb-bos">${ç("Boş")}</span>`}</button>`;
        }).join("")}</div>
        <p class="kucuk" style="margin:14px 0 8px">${ç("Duruş")}</p>
        <div class="tb-duruslar" role="group" aria-label="${ç("Duruş")}">${Object.entries(DURUS).map(([k, x]) =>
          `<button class="tb-durus" data-durus="${k}" aria-pressed="${secim.durus === k}"><b>${x.ad}</b><span>${x.yener}</span></button>`).join("")}</div>
        ${plan ? `<div class="satir" style="margin-top:16px"><button class="dugme altin" id="tb-plan">${ikon("send")}${ç("Planı gönder")}</button></div>` : `
        <div class="tb-vur-alan">
          <button class="vur-dugme" id="tb-vur" style="--oran:${secim.vurus / (s?.hits_per_tick ?? 10)}" aria-label="${ç("Vur")}">
            <span>${ç("VUR")}<small>${sayi(secim.vurus)} / ${sayi(s?.hits_per_tick ?? 10)}</small></span></button>
          <span class="kucuk">${ç("Vuruşun {puan} puan. {n} vuruşta adım kendiliğinden gönderilir.", { puan: s ? puan(s.power) : "?", n: Number(s?.hits_per_tick ?? 10) })}</span>
          <button class="dugme ikincil kucuk-d" id="tb-gonder" ${secim.vurus < 1 ? "disabled" : ""}>${ç("Adımı gönder")}</button>
        </div>`}`}
      </section>`;
    };

    const sonucGecmisi = [];
    const sonucKutusu = () => {
      const r = sonuc;
      const kazandi = Number(r.slice_x10) > 5_000_000;
      const bot = r.opponent?.[0] ?? r.opponent_plans?.[0];
      return `<div class="tb-sonuc">
        <div class="${kazandi ? "bilgi-kutusu" : "hata-kutusu"}">${ikon(kazandi ? "trophy" : "circle-alert")}
          <span>${kazandi ? ç("Bu adımı sen aldın: dilim payın <b>{pay}</b>.", { pay: payYuzde(Number(r.slice_x10) / 10) })
            : ç("Bu adımı bot aldı: dilim payın <b>{pay}</b>.", { pay: payYuzde(Number(r.slice_x10) / 10) })}
          ${bot ? ç("Bot {kesim} kesimindeydi, duruşu <b>{durus}</b>.", { kesim: esc(KESIM[bot.sector]?.ad ?? bot.sector), durus: esc(DURUS[bot.stance]?.ad ?? bot.stance) }) : ""}</span></div>
        ${["left", "center", "right"].map((k) => {
          const x = r.sectors?.[k];
          const pay = typeof x === "object" ? Number(x?.share) : Number(x);
          return `<div class="pay-satir"><span>${KESIM[k].ad}</span><span class="pay-cubuk"><i style="width:${Math.round(pay / 10000)}%"></i></span><b>${payYuzde(pay)}</b></div>`;
        }).join("")}
        ${r.real_cost ? `<p class="kucuk">${r.real_cost.ammo
          ? ç("Gerçek cephede bu adım <b>{enerji} enerji</b>, <b>{muhimmat} mühimmat</b> ve <b>{lojistik} lojistik paketi</b> harcardı.",
            { enerji: Number(r.real_cost.energy), muhimmat: Number(r.real_cost.ammo), lojistik: Number(r.real_cost.logistics) })
          : ç("Gerçek cephede bu adım <b>{enerji} enerji</b> ve <b>{lojistik} lojistik paketi</b> harcardı.",
            { enerji: Number(r.real_cost.energy), lojistik: Number(r.real_cost.logistics) })}</p>` : ""}
        <div class="satir"><button class="dugme altin" id="tb-sonraki">${ikon("arrow-right")}${r.session.status === "finished" ? ç("Sonucu gör") : ç("Sonraki adım")}</button></div>
      </div>`;
    };

    // Sayfa iskeleti bir kez kurulur; tatbikat, kampanya listesi ve arena kendi kutularında yenilenir (arena silinmesin).
    kap.innerHTML = `<div class="sayfa">
      <div class="sayfa-bas"><div><p class="ust-yazi">${ç("Cephe")}</p><h1 class="b1">${ç("Savaş ve tatbikat")}</h1><p class="aciklama" id="cephe-aciklama"></p></div></div>
      <div id="cephe-arena"></div>
      <div class="izgara iki" style="margin-top:20px"><div class="yigin" id="cephe-tatbikat"></div><section class="kart" id="cephe-kampanyalar"></section></div>
    </div>`;
    const tb = $("#cephe-tatbikat", kap), kl = $("#cephe-kampanyalar", kap), ar = $("#cephe-arena", kap);
    let secili = null, arenaBirak = null;

    function kampanyalarCiz() {
      $("#cephe-aciklama", kap).textContent = a.live_war ? ç("Ülkenin süren bir savaşı var: cepheye gir, vur.") : a.campaigns?.length ? ç("Ülkenin hazırlıktaki bir kampanyası var.") : ç("Şu an ülkenin süren bir savaşı yok; tatbikatla hazırlanabilirsin.");
      kl.innerHTML = `<div class="kart-bas"><div><p class="ust-yazi">${ç("Ülkenin savaşları")}</p><h2 class="b2">${ç("Kampanyalar")}</h2></div><span class="ik-kutu">${ikon("swords")}</span></div>
        ${a.campaigns?.length ? `<div class="yigin">${a.campaigns.map((c) => {
          const acik = c.status === "active" && c.next_round_at && Date.parse(c.next_round_at) <= Date.now();
          return `<div class="ilk-adim"><span class="ozet-ikon" style="background:var(--mercan-acik);color:var(--mercan-2)">${ikon("swords")}</span>
            <span><b>${esc(bolgeAdi(c.target_region_id))}</b><span class="kucuk">${c.my_side === "attacker" ? ç("Saldırıyoruz") : ç("Savunuyoruz")} · ${c.status === "preparing" ? ç("hazırlık") : acik ? ç("tur sürüyor") : ç("turlar arası")}${c.next_round_at && !acik ? " · " + ç("sıradaki tur {zaman}", { zaman: esc(saatYaz(c.next_round_at)) }) : ""}</span></span>
            ${secili === c.campaign_id ? `<span class="cip altin">${ç("Açık")}</span>` : `<button class="dugme kucuk-d ${acik ? "mercan" : "ikincil"}" data-kampanya="${esc(c.campaign_id)}">${acik ? ç("Cepheye gir") : ç("Aç")}</button>`}</div>`;
        }).join("")}</div>` : `<p class="bos">${ç("Ülkenin açık bir kampanyası yok. Savaşı başkan, meclisin verdiği yetkiyle ilan eder (Ülkem → Meclis).")}</p>`}`;
      for (const b of $$("[data-kampanya]", kl)) b.onclick = () => arenaAc(b.dataset.kampanya);
    }

    async function arenaAc(id) {
      if (arenaBirak) { try { arenaBirak(); } catch (e) { console.error(e); } arenaBirak = null; }
      secili = id;
      try { sessionStorage.setItem("civora.kampanya", id); } catch { /* yok */ }
      kampanyalarCiz();
      ar.innerHTML = `<div class="kart yuk-kart">${ç("Cephe yükleniyor…")}</div>`;
      try { arenaBirak = await CepheArena.ac(ar, id); }
      catch (e) { ar.innerHTML = `<div class="hata-kutusu">${ikon("circle-alert")}<span>${esc(hataMetni(e))}</span></div>`; }
    }

    const ciz = () => {
      tb.innerHTML = tatbikatKarti();
      bagla();
    };

    function bagla() {
      $("#tb-basla", tb)?.addEventListener("click", baslat);
      for (const b of $$("[data-kesim]", tb)) b.onclick = () => { secim.kesim = b.dataset.kesim; ciz(); };
      for (const b of $$("[data-durus]", tb)) b.onclick = () => { secim.durus = b.dataset.durus; ciz(); };
      const vur = $("#tb-vur", tb);
      if (vur) vur.addEventListener("pointerdown", (e) => { e.preventDefault(); vurus(); });
      $("#tb-gonder", tb)?.addEventListener("click", gonder);
      $("#tb-plan", tb)?.addEventListener("click", gonder);
      $("#tb-sonraki", tb)?.addEventListener("click", sonraki);
    }

    async function baslat() {
      try {
        oturum = await Sunucu.yap("drill_start");
        sonuc = null;
        bitis = null;
        secim.vurus = 0;
        ciz();
      } catch (e) { tost(hataMetni(e), "circle-alert"); }
    }

    function vurus() {
      if (gonderiliyor || sonuc) return;
      const tavan = a.soldier?.hits_per_tick ?? 10;
      if (secim.vurus >= tavan) return;
      secim.vurus++;
      const v = $("#tb-vur", tb);
      v.style.setProperty("--oran", String(secim.vurus / tavan));
      $("small", v).textContent = `${secim.vurus} / ${tavan}`;
      $("#tb-gonder", tb).disabled = false;
      if (navigator.vibrate) navigator.vibrate(8);
      if (secim.vurus >= tavan) gonder();
    }

    async function gonder() {
      if (gonderiliyor) return;
      gonderiliyor = true;
      try {
        sonuc = oturum.mode === "hits"
          ? await Sunucu.yap("drill_hit", { p_session: oturum.session_id, p_sector: secim.kesim, p_stance: secim.durus, p_hits: Math.max(1, secim.vurus) })
          : await Sunucu.yap("drill_step", { p_session: oturum.session_id, p_sector: secim.kesim, p_stance: secim.durus });
        sonucGecmisi[sonuc.step_no - 1] = Number(sonuc.slice_x10);
        if (sonuc.basic_training_completed_now) bitis = { ilk: true };
        ciz();
      } catch (e) {
        tost(hataMetni(e), "circle-alert");
      } finally {
        gonderiliyor = false;
      }
    }

    async function sonraki() {
      const s = sonuc.session;
      if (s.status === "finished") {
        bitis = { ...(bitis ?? {}), won: s.won, total_x10: s.total_x10, steps_total: s.steps_total };
        oturum = null;
        sonucGecmisi.length = 0;
        a = await Durum.askerlik();
      } else {
        oturum = s;
      }
      sonuc = null;
      secim.vurus = 0;
      ciz();
    }

    // Açık bir tatbikat varsa kaldığı yerden.
    if (a.drill?.open_session) oturum = a.drill.open_session;
    ciz();
    kampanyalarCiz();
    // Arena: önce seçilmiş (bu oturumda), yoksa turu süren, yoksa ilk kampanya.
    let onceki = null;
    try { onceki = sessionStorage.getItem("civora.kampanya"); } catch { /* yok */ }
    const kl0 = a.campaigns ?? [];
    const ilk = kl0.find((c) => c.campaign_id === onceki) ?? kl0.find((c) => c.status === "active" && c.next_round_at && Date.parse(c.next_round_at) <= Date.now()) ?? kl0[0];
    if (ilk) await arenaAc(ilk.campaign_id);
    const b1 = Durum.dinle("askerlik", (x) => {
      const eskiSayi = (a.campaigns ?? []).map((c) => c.campaign_id + c.status).join();
      a = x;
      if (!oturum && !sonuc) ciz();
      if ((a.campaigns ?? []).map((c) => c.campaign_id + c.status).join() !== eskiSayi) {
        kampanyalarCiz();
        if (!secili && a.campaigns?.length) arenaAc(a.campaigns[0].campaign_id);
      }
    });
    return () => { b1(); if (arenaBirak) arenaBirak(); };
  },
});

// ===== 23_ayarlar.js =====
