    const yildiz5 = (r1, r2, dy = 0) => { const p = []; for (let i = 0; i < 10; i++) { const a = (i / 10) * Math.PI * 2 - Math.PI / 2, r = i % 2 ? r2 : r1; p.push([Math.cos(a) * r, Math.sin(a) * r + dy]); } yol(p, true, true); };
